  1→/**
  2→ * SDK Integration Test — tests real API operations (requires running API).
  3→ * Run: pnpm --filter @cipherbox/sdk vitest run src/__tests__/integration.test.ts --no-coverage
  4→ */
  5→import { describe, it, expect } from 'vitest';
  6→import { CipherBoxClient } from '../client';
  7→import { setApiClientConfig } from '@cipherbox/api-client';
  8→import { initializeVault, encryptVaultKeys } from '@cipherbox/core';
  9→import { deriveIpnsName, hexToBytes, bytesToHex } from '@cipherbox/crypto';
 10→
 11→const API = 'http://localhost:3000';
 12→const SECRET = 'e2e-test-secret-do-not-use-in-production';
 13→
 14→const describeIf = process.env.CI ? describe.skip : describe;
 15→
 16→describeIf('SDK Integration (live API)', () => {
 17→  it(
 18→    'full lifecycle: folder CRUD, upload, download, rename, delete',
 19→    { timeout: 120000 },
 20→    async () => {
 21→      const email = `sdk-int-${Date.now()}@example.com`;
 22→
 23→      // --- Setup ---
 24→      const loginRes = await fetch(`${API}/auth/test-login`, {
 25→        method: 'POST',
 26→        headers: { 'Content-Type': 'application/json' },
 27→        body: JSON.stringify({ email, secret: SECRET }),
 28→      });
 29→      expect(loginRes.ok).toBe(true);
 30→      const { accessToken, publicKeyHex, privateKeyHex } = await loginRes.json();
 31→      const publicKey = hexToBytes(publicKeyHex);
 32→      const privateKey = hexToBytes(privateKeyHex);
 33→
 34→      const vault = await initializeVault(privateKey);
 35→      const encrypted = await encryptVaultKeys(vault, publicKey);
 36→      const rootIpnsName = await deriveIpnsName(vault.rootIpnsKeypair.publicKey);
 37→
 38→      const initRes = await fetch(`${API}/vault/init`, {
 39→        method: 'POST',
 40→        headers: { Authorization: `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
 41→        body: JSON.stringify({
 42→          ownerPublicKey: bytesToHex(publicKey),
 43→          encryptedRootFolderKey: bytesToHex(encrypted.encryptedRootFolderKey),
 44→          encryptedRootIpnsPrivateKey: bytesToHex(encrypted.encryptedIpnsPrivateKey),
 45→          rootIpnsName,
 46→        }),
 47→      });
 48→      expect(initRes.ok).toBe(true);
 49→
 50→      setApiClientConfig({ baseUrl: API, getAccessToken: async () => accessToken });
 51→
 52→      const client = new CipherBoxClient({
 53→        apiUrl: API,
 54→        getAccessToken: async () => accessToken,
 55→        vaultKeypair: { publicKey, privateKey },
 56→        rootIpnsName,
 57→        rootFolderKey: vault.rootFolderKey,
 58→      });
 59→      client.registerFolder(rootIpnsName, vault.rootFolderKey, vault.rootIpnsKeypair, [], 0n);
 60→
 61→      try {
 62→        // 1. Create folder
 63→        const folder = await client.createFolder(rootIpnsName, 'TestFolder');
 64→        expect(folder.id).toBeTruthy();
 65→        expect(folder.ipnsName).toMatch(/^k51/);
 66→        expect(folder.folderKey.length).toBe(32);
 67→        expect(folder.ipnsPrivateKey.length).toBeGreaterThan(0);
 68→        console.log('  ✓ Create folder');
 69→
 70→        // 2. Upload file
 71→        const originalContent = 'Hello SDK! ' + Date.now();
 72→        const fileData = new TextEncoder().encode(originalContent);
 73→        const upload = await client.uploadFile(rootIpnsName, fileData, 'test.txt', 'text/plain');
 74→        expect(upload.cid).toBeTruthy();
 75→        console.log('  ✓ Upload file');
 76→
 77→        // 3. Download via downloadFromIpns (same path the web app uses)
 78→        const root = (client as any).folderTree.get(rootIpnsName);
 79→        const fileChild = root?.children.find(
 80→          (c: any) => c.type === 'file' && c.name === 'test.txt'
 81→        );
 82→        expect(fileChild).toBeTruthy();
 83→
 84→        const downloaded = await client.downloadFromIpns(
 85→          fileChild.fileMetaIpnsName,
 86→          vault.rootFolderKey
 87→        );
 88→        const downloadedText = new TextDecoder().decode(downloaded);
 89→        expect(downloadedText).toBe(originalContent);
 90→        console.log('  ✓ Download via downloadFromIpns (content verified)');
 91→
 92→        // 4. Rename file
 93→        await client.renameItem(rootIpnsName, fileChild.id, 'renamed.txt');
 94→        const afterRename = (client as any).folderTree.get(rootIpnsName);
 95→        expect(afterRename.children.find((c: any) => c.name === 'renamed.txt')).toBeTruthy();
 96→        console.log('  ✓ Rename file');
 97→
 98→        // 5. Rename folder
 99→        await client.renameItem(rootIpnsName, folder.id, 'RenamedFolder');
100→        const afterFolderRename = (client as any).folderTree.get(rootIpnsName);
101→        expect(
102→          afterFolderRename.children.find((c: any) => c.name === 'RenamedFolder')
103→        ).toBeTruthy();
104→        console.log('  ✓ Rename folder');
105→
106→        // 6. Delete file
107→        const deleteResult = await client.deleteItem(rootIpnsName, fileChild.id);
108→        expect(deleteResult.removedItem.id).toBe(fileChild.id);
109→        console.log('  ✓ Delete file');
110→
111→        // 7. Delete folder
112→        const folderDelete = await client.deleteItem(rootIpnsName, folder.id);
113→        expect(folderDelete.removedItem.id).toBe(folder.id);
114→        console.log('  ✓ Delete folder');
115→
116→        // Verify root is empty
117→        const finalRoot = (client as any).folderTree.get(rootIpnsName);
118→        expect(finalRoot.children.length).toBe(0);
119→        console.log('  ✓ Root folder empty');
120→      } finally {
121→        client.destroy();
122→      }
123→    }
124→  );
125→
126→  it(
127→    'bin lifecycle: loadBin on fresh account, deleteToBin, verify bin entries',
128→    { timeout: 120000 },
129→    async () => {
130→      const email = `sdk-bin-${Date.now()}@example.com`;
131→
132→      // --- Setup (same as main test) ---
133→      const loginRes = await fetch(`${API}/auth/test-login`, {
134→        method: 'POST',
135→        headers: { 'Content-Type': 'application/json' },
136→        body: JSON.stringify({ email, secret: SECRET }),
137→      });
138→      expect(loginRes.ok).toBe(true);
139→      const { accessToken, publicKeyHex, privateKeyHex } = await loginRes.json();
140→      const publicKey = hexToBytes(publicKeyHex);
141→      const privateKey = hexToBytes(privateKeyHex);
142→
143→      const vault = await initializeVault(privateKey);
144→      const encrypted = await encryptVaultKeys(vault, publicKey);
145→      const rootIpnsName = await deriveIpnsName(vault.rootIpnsKeypair.publicKey);
146→
147→      const initRes = await fetch(`${API}/vault/init`, {
148→        method: 'POST',
149→        headers: { Authorization: `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
150→        body: JSON.stringify({
151→          ownerPublicKey: bytesToHex(publicKey),
152→          encryptedRootFolderKey: bytesToHex(encrypted.encryptedRootFolderKey),
153→          encryptedRootIpnsPrivateKey: bytesToHex(encrypted.encryptedIpnsPrivateKey),
154→          rootIpnsName,
155→        }),
156→      });
157→      expect(initRes.ok).toBe(true);
158→
159→      setApiClientConfig({ baseUrl: API, getAccessToken: async () => accessToken });
160→
161→      const client = new CipherBoxClient({
162→        apiUrl: API,
163→        getAccessToken: async () => accessToken,
164→        vaultKeypair: { publicKey, privateKey },
165→        rootIpnsName,
166→        rootFolderKey: vault.rootFolderKey,
167→      });
168→      client.registerFolder(rootIpnsName, vault.rootFolderKey, vault.rootIpnsKeypair, [], 0n);
169→
170→      try {
171→        // 1. loadBin on fresh account — should return empty state (not null)
172→        const binState = await client.loadBin();
173→        expect(binState).toBeTruthy();
174→        expect(binState.entries).toEqual([]);
175→        expect(binState.sequenceNumber).toBe(0);
176→        console.log('  ✓ loadBin on fresh account returns empty state');
177→
178→        // 2. Upload a file
179→        const fileData = new TextEncoder().encode('bin test ' + Date.now());
180→        await client.uploadFile(rootIpnsName, fileData, 'bin-test.txt', 'text/plain');
181→        const root = (client as any).folderTree.get(rootIpnsName);
182→        const fileChild = root.children.find((c: any) => c.name === 'bin-test.txt');
183→        expect(fileChild).toBeTruthy();
184→        console.log('  ✓ Uploaded file for bin test');
185→
186→        // 3. deleteToBin — should NOT throw "Bin not loaded"
187→        await client.deleteToBin(rootIpnsName, fileChild.id, 'My Vault');
188→        console.log('  ✓ deleteToBin succeeded (no "Bin not loaded" error)');
189→
190→        // 4. Verify bin state has the entry
191→        const updatedBin = (client as any).binState;
192→        expect(updatedBin.entries.length).toBe(1);
193→        expect(updatedBin.entries[0].name).toBe('bin-test.txt');
194→        expect(updatedBin.entries[0].itemType).toBe('file');
195→        console.log('  ✓ Bin contains deleted file entry');
196→
197→        // 5. Verify file removed from root
198→        const rootAfterDelete = (client as any).folderTree.get(rootIpnsName);
199→        expect(rootAfterDelete.children.length).toBe(0);
200→        console.log('  ✓ File removed from root folder');
201→
202→        // 6. Reload bin from IPNS — should find the persisted entry
203→        const reloaded = await client.loadBin();
204→        expect(reloaded.entries.length).toBe(1);
205→        expect(reloaded.entries[0].name).toBe('bin-test.txt');
206→        console.log('  ✓ Bin entry persisted to IPNS (verified via reload)');
207→      } finally {
208→        client.destroy();
209→      }
210→    }
211→  );
212→});
