1215→+/**
1216→+ * Upload Throughput Scenario
1217→+ *
1218→+ * N clients each upload M files (1KB-500KB), measuring upload pipeline
1219→+ * throughput including IPNS publish per file.
1220→+ */
1221→+
1222→+import { describe, it, afterAll } from 'vitest';
1223→+import { createClientPool, destroyClientPool, type PoolClient } from '../harness/client-pool';
1224→+import { MetricsCollector } from '../harness/metrics';
1225→+import { printSummary, toJsonReport } from '../harness/reporter';
1226→+import { runFileWorkload } from '../workloads/file-workload';
1227→+
1228→+const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '10', 10);
1229→+const FILES_PER_CLIENT = 20;
1230→+
1231→+describe('Upload Throughput', () => {
1232→+  let pool: PoolClient[] = [];
1233→+
1234→+  afterAll(async () => {
1235→+    await destroyClientPool(pool);
1236→+  });
1237→+
1238→+  it(`${NUM_CLIENTS} clients × ${FILES_PER_CLIENT} files (1KB-500KB)`, async () => {
1239→+    pool = await createClientPool({
1240→+      clientCount: NUM_CLIENTS,
1241→+      label: 'upload-throughput',
1242→+    });
1243→+
1244→+    const globalMetrics = new MetricsCollector();
1245→+    globalMetrics.start();
1246→+
1247→+    // Run all client workloads concurrently
1248→+    const results = await Promise.allSettled(
1249→+      pool.map((pc) => {
1250→+        pc.metrics.start();
1251→+        return runFileWorkload(pc, {
1252→+          fileCount: FILES_PER_CLIENT,
1253→+          minSize: 1_024,
1254→+          maxSize: 500 * 1_024,
1255→+          verifyDownloads: false,
1256→+        }).finally(() => pc.metrics.stop());
1257→+      })
1258→+    );
1259→+
1260→+    globalMetrics.stop();
1261→+
1262→+    // Aggregate metrics from all clients
1263→+    const allMetrics = new MetricsCollector();
1264→+    allMetrics.start();
1265→+    for (const pc of pool) {
1266→+      for (const sample of pc.metrics.getRawSamples()) {
1267→+        allMetrics.record(sample);
1268→+      }
1269→+    }
1270→+    allMetrics.stop();
1271→+
1272→+    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
1273→+    const failed = results.filter((r) => r.status === 'rejected').length;
1274→+    console.log(`\nClients completed: ${succeeded} succeeded, ${failed} failed`);
1275→+
1276→+    const metrics = allMetrics.getMetrics();
1277→+    const totalDuration =
1278→+      Math.max(...pool.map((pc) => pc.metrics.getRawSamples().at(-1)?.timestamp ?? 0)) -
1279→+      Math.min(...pool.map((pc) => pc.metrics.getRawSamples()[0]?.timestamp ?? Date.now()));
1280→+
1281→+    printSummary('Upload Throughput', metrics, totalDuration, pool.length);
1282→+
1283→+    // Write JSON report
1284→+    const json = toJsonReport('upload-throughput', metrics, totalDuration, pool.length);
1285→+    console.log('\nJSON Report:\n' + json);
1286→+  });
1287→+});
