1632→+/**
1633→+ * Multi-Account Test Fixture
1634→+ *
1635→+ * Creates N test accounts for tests that require interaction between users
1636→+ * (sharing, invite links). Handles the setApiClientConfig singleton caveat
1637→+ * by switching the active account before each operation.
1638→+ */
1639→+
1640→+import { setApiClientConfig } from '@cipherbox/api-client';
1641→+import { createTestContext, deleteTestAccount, type TestContext, API_URL } from './test-harness';
1642→+
1643→+export interface MultiAccountFixture {
1644→+  /** All created test contexts, indexed by label */
1645→+  accounts: Map<string, TestContext>;
1646→+  /**
1647→+   * Switch the api-client singleton to the given account.
1648→+   * Must be called before any operation that uses the singleton
1649→+   * (e.g., sdk-core IPNS functions).
1650→+   */
1651→+  switchTo: (label: string) => void;
1652→+  /** Destroy all clients and delete all accounts */
1653→+  cleanupAll: () => Promise<void>;
1654→+}
1655→+
1656→+/**
1657→+ * Create N test accounts with the given labels.
1658→+ *
1659→+ * @example
1660→+ * const fixture = await createMultiAccountFixture(['alice', 'bob']);
1661→+ * const alice = fixture.accounts.get('alice')!;
1662→+ * const bob = fixture.accounts.get('bob')!;
1663→+ */
1664→+export async function createMultiAccountFixture(labels: string[]): Promise<MultiAccountFixture> {
1665→+  const accounts = new Map<string, TestContext>();
1666→+
1667→+  // Create accounts sequentially to avoid race conditions on vault init
1668→+  for (const label of labels) {
1669→+    const ctx = await createTestContext(label);
1670→+    accounts.set(label, ctx);
1671→+  }
1672→+
1673→+  const switchTo = (label: string): void => {
1674→+    const ctx = accounts.get(label);
1675→+    if (!ctx) throw new Error(`No account with label "${label}"`);
1676→+    setApiClientConfig({
1677→+      baseUrl: API_URL,
1678→+      getAccessToken: async () => ctx.accessToken,
1679→+    });
