1698→+/**
1699→+ * SDK E2E Test Harness
1700→+ *
1701→+ * Creates authenticated CipherBoxClient instances backed by real API accounts.
1702→+ * Extracted from packages/sdk/src/__tests__/integration.test.ts pattern.
1703→+ *
1704→+ * Each call to createTestContext() creates a unique user via /auth/test-login,
1705→+ * initializes their vault, and returns a ready-to-use CipherBoxClient.
1706→+ */
1707→+
1708→+import { CipherBoxClient } from '@cipherbox/sdk';
1709→+import { setApiClientConfig } from '@cipherbox/api-client';
1710→+import { initializeVault, encryptVaultKeys } from '@cipherbox/core';
1711→+import { deriveIpnsName, hexToBytes, bytesToHex } from '@cipherbox/crypto';
1712→+
1713→+const API_URL = process.env.SDK_E2E_API_URL ?? 'http://localhost:3000';
1714→+const SECRET = process.env.SDK_E2E_SECRET ?? 'e2e-test-secret-do-not-use-in-production';
1715→+
1716→+export interface TestContext {
1717→+  client: CipherBoxClient;
1718→+  accessToken: string;
1719→+  refreshToken: string;
1720→+  publicKey: Uint8Array;
1721→+  privateKey: Uint8Array;
1722→+  rootIpnsName: string;
1723→+  rootFolderKey: Uint8Array;
1724→+  rootIpnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
1725→+  email: string;
1726→+  /** Destroy the client and zero key material */
1727→+  cleanup: () => void;
1728→+}
1729→+
1730→+/**
1731→+ * Create a fully-initialized test context with a new user account.
1732→+ *
1733→+ * Steps:
1734→+ * 1. POST /auth/test-login → accessToken + keypair
1735→+ * 2. initializeVault(privateKey) → rootFolderKey, rootIpnsKeypair
1736→+ * 3. encryptVaultKeys + POST /vault/init
1737→+ * 4. setApiClientConfig (singleton — see multi-account caveat)
1738→+ * 5. new CipherBoxClient + registerFolder
1739→+ */
1740→+export async function createTestContext(label: string): Promise<TestContext> {
1741→+  const email = `sdk-e2e-${label}-${Date.now()}@example.com`;
1742→+
1743→+  // 1. Authenticate
1744→+  const loginRes = await fetch(`${API_URL}/auth/test-login`, {
1745→+    method: 'POST',
1746→+    headers: { 'Content-Type': 'application/json' },
1747→+    body: JSON.stringify({ email, secret: SECRET }),
1748→+  });
1749→+  if (!loginRes.ok) {
1750→+    throw new Error(`test-login failed (${loginRes.status}): ${await loginRes.text()}`);
1751→+  }
1752→+  const { accessToken, refreshToken, publicKeyHex, privateKeyHex } = await loginRes.json();
1753→+  const publicKey = hexToBytes(publicKeyHex);
1754→+  const privateKey = hexToBytes(privateKeyHex);
1755→+
1756→+  // 2. Initialize vault
1757→+  const vault = await initializeVault(privateKey);
1758→+  const encrypted = await encryptVaultKeys(vault, publicKey);
1759→+  const rootIpnsName = await deriveIpnsName(vault.rootIpnsKeypair.publicKey);
1760→+
1761→+  // 3. Register vault on server
1762→+  const initRes = await fetch(`${API_URL}/vault/init`, {
1763→+    method: 'POST',
1764→+    headers: {
1765→+      Authorization: `Bearer ${accessToken}`,
1766→+      'Content-Type': 'application/json',
1767→+    },
1768→+    body: JSON.stringify({
1769→+      ownerPublicKey: bytesToHex(publicKey),
1770→+      encryptedRootFolderKey: bytesToHex(encrypted.encryptedRootFolderKey),
1771→+      encryptedRootIpnsPrivateKey: bytesToHex(encrypted.encryptedIpnsPrivateKey),
1772→+      rootIpnsName,
1773→+    }),
1774→+  });
1775→+  if (!initRes.ok) {
1776→+    throw new Error(`vault/init failed (${initRes.status}): ${await initRes.text()}`);
1777→+  }
1778→+
1779→+  // 4. Configure API client singleton
1780→+  setApiClientConfig({
1781→+    baseUrl: API_URL,
1782→+    getAccessToken: async () => accessToken,
1783→+  });
1784→+
1785→+  // 5. Create and configure CipherBoxClient
1786→+  const client = new CipherBoxClient({
1787→+    apiUrl: API_URL,
1788→+    getAccessToken: async () => accessToken,
1789→+    vaultKeypair: { publicKey, privateKey },
1790→+    rootIpnsName,
1791→+    rootFolderKey: vault.rootFolderKey,
1792→+  });
1793→+  client.registerFolder(rootIpnsName, vault.rootFolderKey, vault.rootIpnsKeypair, [], 0n);
1794→+
1795→+  return {
1796→+    client,
1797→+    accessToken,
1798→+    refreshToken,
1799→+    publicKey,
1800→+    privateKey,
1801→+    rootIpnsName,
1802→+    rootFolderKey: vault.rootFolderKey,
1803→+    rootIpnsKeypair: vault.rootIpnsKeypair,
1804→+    email,
1805→+    cleanup: () => client.destroy(),
1806→+  };
1807→+}
1808→+
1809→+/**
1810→+ * Delete a test account (cleanup after tests).
1811→+ * Uses the access token from the test context.
1812→+ */
1813→+export async function deleteTestAccount(ctx: TestContext): Promise<void> {
1814→+  try {
1815→+    const res = await fetch(`${API_URL}/auth/account`, {
1816→+      method: 'DELETE',
1817→+      headers: {
1818→+        Authorization: `Bearer ${ctx.accessToken}`,
1819→+        'Content-Type': 'application/json',
1820→+      },
1821→+      body: JSON.stringify({ confirmation: 'DELETE' }),
1822→+    });
1823→+    if (!res.ok) {
1824→+      console.warn(`Account deletion failed (${res.status}): ${await res.text()}`);
1825→+    }
1826→+  } catch (err) {
1827→+    console.warn(`Account deletion error: ${(err as Error).message}`);
1828→+  }
1829→+}
