  1→/**
  2→ * SDK E2E Test Harness
  3→ *
  4→ * Creates authenticated CipherBoxClient instances backed by real API accounts.
  5→ * Extracted from packages/sdk/src/__tests__/integration.test.ts pattern.
  6→ *
  7→ * Each call to createTestContext() creates a unique user via /auth/test-login,
  8→ * initializes their vault, and returns a ready-to-use CipherBoxClient.
  9→ */
 10→
 11→import { CipherBoxClient } from '@cipherbox/sdk';
 12→import { setApiClientConfig } from '@cipherbox/api-client';
 13→import { initializeVault, encryptVaultKeys } from '@cipherbox/core';
 14→import { deriveIpnsName, hexToBytes, bytesToHex } from '@cipherbox/crypto';
 15→
 16→const API_URL = process.env.SDK_E2E_API_URL ?? 'http://localhost:3000';
 17→const SECRET = process.env.SDK_E2E_SECRET ?? 'e2e-test-secret-do-not-use-in-production';
 18→
 19→export interface TestContext {
 20→  client: CipherBoxClient;
 21→  accessToken: string;
 22→  refreshToken: string;
 23→  publicKey: Uint8Array;
 24→  privateKey: Uint8Array;
 25→  rootIpnsName: string;
 26→  rootFolderKey: Uint8Array;
 27→  rootIpnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
 28→  email: string;
 29→  /** Destroy the client and zero key material */
 30→  cleanup: () => void;
 31→}
 32→
 33→/**
 34→ * Create a fully-initialized test context with a new user account.
 35→ *
 36→ * Steps:
 37→ * 1. POST /auth/test-login → accessToken + keypair
 38→ * 2. initializeVault(privateKey) → rootFolderKey, rootIpnsKeypair
 39→ * 3. encryptVaultKeys + POST /vault/init
 40→ * 4. setApiClientConfig (singleton — see multi-account caveat)
 41→ * 5. new CipherBoxClient + registerFolder
 42→ */
 43→export async function createTestContext(label: string): Promise<TestContext> {
 44→  const email = `sdk-e2e-${label}-${Date.now()}@example.com`;
 45→
 46→  // 1. Authenticate
 47→  const loginRes = await fetch(`${API_URL}/auth/test-login`, {
 48→    method: 'POST',
 49→    headers: { 'Content-Type': 'application/json' },
 50→    body: JSON.stringify({ email, secret: SECRET }),
 51→  });
 52→  if (!loginRes.ok) {
 53→    throw new Error(`test-login failed (${loginRes.status}): ${await loginRes.text()}`);
 54→  }
 55→  const { accessToken, refreshToken, publicKeyHex, privateKeyHex } = await loginRes.json();
 56→  const publicKey = hexToBytes(publicKeyHex);
 57→  const privateKey = hexToBytes(privateKeyHex);
 58→
 59→  // 2. Initialize vault
 60→  const vault = await initializeVault(privateKey);
 61→  const encrypted = await encryptVaultKeys(vault, publicKey);
 62→  const rootIpnsName = await deriveIpnsName(vault.rootIpnsKeypair.publicKey);
 63→
 64→  // 3. Register vault on server
 65→  const initRes = await fetch(`${API_URL}/vault/init`, {
 66→    method: 'POST',
 67→    headers: {
 68→      Authorization: `Bearer ${accessToken}`,
 69→      'Content-Type': 'application/json',
 70→    },
 71→    body: JSON.stringify({
 72→      ownerPublicKey: bytesToHex(publicKey),
 73→      encryptedRootFolderKey: bytesToHex(encrypted.encryptedRootFolderKey),
 74→      encryptedRootIpnsPrivateKey: bytesToHex(encrypted.encryptedIpnsPrivateKey),
 75→      rootIpnsName,
 76→    }),
 77→  });
 78→  if (!initRes.ok) {
 79→    throw new Error(`vault/init failed (${initRes.status}): ${await initRes.text()}`);
 80→  }
 81→
 82→  // 4. Configure API client singleton
 83→  setApiClientConfig({
 84→    baseUrl: API_URL,
 85→    getAccessToken: async () => accessToken,
 86→  });
 87→
 88→  // 5. Create and configure CipherBoxClient
 89→  const client = new CipherBoxClient({
 90→    apiUrl: API_URL,
 91→    getAccessToken: async () => accessToken,
 92→    vaultKeypair: { publicKey, privateKey },
 93→    rootIpnsName,
 94→    rootFolderKey: vault.rootFolderKey,
 95→  });
 96→  client.registerFolder(rootIpnsName, vault.rootFolderKey, vault.rootIpnsKeypair, [], 0n);
 97→
 98→  return {
 99→    client,
100→    accessToken,
101→    refreshToken,
102→    publicKey,
103→    privateKey,
104→    rootIpnsName,
105→    rootFolderKey: vault.rootFolderKey,
106→    rootIpnsKeypair: vault.rootIpnsKeypair,
107→    email,
108→    cleanup: () => client.destroy(),
109→  };
110→}
