112→/**
113→ * Delete a test account (cleanup after tests).
114→ * Uses the access token from the test context.
115→ */
116→export async function deleteTestAccount(ctx: TestContext): Promise<void> {
117→  try {
118→    const res = await fetch(`${API_URL}/auth/account`, {
119→      method: 'DELETE',
120→      headers: {
121→        Authorization: `Bearer ${ctx.accessToken}`,
122→        'Content-Type': 'application/json',
123→      },
124→      body: JSON.stringify({ confirmation: 'DELETE' }),
125→    });
126→    if (!res.ok) {
127→      console.warn(`Account deletion failed (${res.status}): ${await res.text()}`);
128→    }
129→  } catch (err) {
130→    console.warn(`Account deletion error: ${(err as Error).message}`);
131→  }
132→}
