  1→/**
  2→ * Load Test Metrics Collection
  3→ *
  4→ * Collects per-operation latency, throughput, and error counts.
  5→ * Uses performance.now() for high-resolution timing.
  6→ */
  7→
  8→export interface OperationMetrics {
  9→  operation: string;
 10→  count: number;
 11→  errors: number;
 12→  latency: { p50: number; p95: number; p99: number; max: number; min: number; avg: number };
 13→  throughputOpsPerSec: number;
 14→  bytesTransferred?: number;
 15→}
 16→
 17→export interface OperationSample {
 18→  operation: string;
 19→  durationMs: number;
 20→  success: boolean;
 21→  bytes?: number;
 22→  timestamp: number;
 23→}
 24→
 25→export class MetricsCollector {
 26→  private samples: OperationSample[] = [];
 27→  private startTime = 0;
 28→  private endTime = 0;
 29→
 30→  start(): void {
 31→    this.startTime = performance.now();
 32→  }
 33→
 34→  stop(): void {
 35→    this.endTime = performance.now();
 36→  }
 37→
 38→  record(sample: OperationSample): void {
 39→    this.samples.push(sample);
 40→  }
 41→
 42→  /**
 43→   * Wrap an async operation to automatically record metrics.
 44→   */
 45→  async measure<T>(operation: string, fn: () => Promise<T>, bytes?: number): Promise<T> {
 46→    const start = performance.now();
 47→    try {
 48→      const result = await fn();
 49→      this.record({
 50→        operation,
 51→        durationMs: performance.now() - start,
 52→        success: true,
 53→        bytes,
 54→        timestamp: Date.now(),
 55→      });
 56→      return result;
 57→    } catch (err) {
 58→      this.record({
 59→        operation,
 60→        durationMs: performance.now() - start,
 61→        success: false,
 62→        bytes,
 63→        timestamp: Date.now(),
 64→      });
 65→      throw err;
 66→    }
 67→  }
 68→
 69→  /**
 70→   * Get aggregated metrics per operation type.
 71→   */
 72→  getMetrics(): OperationMetrics[] {
 73→    const elapsed = (this.endTime || performance.now()) - this.startTime;
 74→    const elapsedSec = elapsed / 1000;
 75→
 76→    const grouped = new Map<string, OperationSample[]>();
 77→    for (const s of this.samples) {
 78→      const list = grouped.get(s.operation) ?? [];
 79→      list.push(s);
 80→      grouped.set(s.operation, list);
 81→    }
 82→
 83→    const metrics: OperationMetrics[] = [];
 84→    for (const [op, samples] of grouped) {
 85→      const durations = samples.map((s) => s.durationMs).sort((a, b) => a - b);
 86→      const errors = samples.filter((s) => !s.success).length;
 87→      const totalBytes = samples.reduce((sum, s) => sum + (s.bytes ?? 0), 0);
 88→
 89→      metrics.push({
 90→        operation: op,
 91→        count: samples.length,
 92→        errors,
 93→        latency: {
 94→          min: durations[0] ?? 0,
 95→          avg: durations.reduce((a, b) => a + b, 0) / durations.length,
 96→          p50: percentile(durations, 0.5),
 97→          p95: percentile(durations, 0.95),
 98→          p99: percentile(durations, 0.99),
 99→          max: durations[durations.length - 1] ?? 0,
100→        },
101→        throughputOpsPerSec: elapsedSec > 0 ? samples.length / elapsedSec : 0,
102→        ...(totalBytes > 0 ? { bytesTransferred: totalBytes } : {}),
103→      });
104→    }
105→
106→    return metrics.sort((a, b) => a.operation.localeCompare(b.operation));
107→  }
108→
109→  /** Total samples collected */
110→  get totalSamples(): number {
111→    return this.samples.length;
112→  }
113→
114→  /** Total errors across all operations */
115→  get totalErrors(): number {
116→    return this.samples.filter((s) => !s.success).length;
117→  }
118→
119→  /** Raw samples (for JSON export) */
120→  getRawSamples(): OperationSample[] {
121→    return [...this.samples];
122→  }
123→}
124→
125→function percentile(sorted: number[], p: number): number {
126→  if (sorted.length === 0) return 0;
127→  const idx = Math.ceil(p * sorted.length) - 1;
128→  return sorted[Math.max(0, idx)];
129→}
