 1→/**
 2→ * Upload Throughput Scenario
 3→ *
 4→ * N clients each upload M files (1KB-500KB), measuring upload pipeline
 5→ * throughput including IPNS publish per file.
 6→ */
 7→
 8→import { describe, it, afterAll } from 'vitest';
 9→import { createClientPool, destroyClientPool, type PoolClient } from '../harness/client-pool';
10→import { MetricsCollector } from '../harness/metrics';
11→import { printSummary, toJsonReport } from '../harness/reporter';
12→import { runFileWorkload } from '../workloads/file-workload';
13→
14→const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '10', 10);
15→const FILES_PER_CLIENT = 20;
16→
17→describe('Upload Throughput', () => {
18→  let pool: PoolClient[] = [];
19→
20→  afterAll(async () => {
21→    await destroyClientPool(pool);
22→  });
23→
24→  it(`${NUM_CLIENTS} clients × ${FILES_PER_CLIENT} files (1KB-500KB)`, async () => {
25→    pool = await createClientPool({
26→      clientCount: NUM_CLIENTS,
27→      label: 'upload-throughput',
28→    });
29→
30→    const globalMetrics = new MetricsCollector();
31→    globalMetrics.start();
32→
33→    // Run all client workloads concurrently
34→    const results = await Promise.allSettled(
35→      pool.map((pc) => {
36→        pc.metrics.start();
37→        return runFileWorkload(pc, {
38→          fileCount: FILES_PER_CLIENT,
39→          minSize: 1_024,
40→          maxSize: 500 * 1_024,
41→          verifyDownloads: false,
42→        }).finally(() => pc.metrics.stop());
43→      })
44→    );
45→
46→    globalMetrics.stop();
47→
48→    // Aggregate metrics from all clients
49→    const allMetrics = new MetricsCollector();
50→    allMetrics.start();
51→    for (const pc of pool) {
52→      for (const sample of pc.metrics.getRawSamples()) {
53→        allMetrics.record(sample);
54→      }
55→    }
56→    allMetrics.stop();
57→
58→    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
59→    const failed = results.filter((r) => r.status === 'rejected').length;
60→    console.log(`\nClients completed: ${succeeded} succeeded, ${failed} failed`);
61→
62→    const metrics = allMetrics.getMetrics();
63→    const totalDuration =
64→      Math.max(...pool.map((pc) => pc.metrics.getRawSamples().at(-1)?.timestamp ?? 0)) -
65→      Math.min(...pool.map((pc) => pc.metrics.getRawSamples()[0]?.timestamp ?? Date.now()));
66→
67→    printSummary('Upload Throughput', metrics, totalDuration, pool.length);
68→
69→    // Write JSON report
70→    const json = toJsonReport('upload-throughput', metrics, totalDuration, pool.length);
71→    console.log('\nJSON Report:\n' + json);
72→  });
73→});
