922→
923→  /** Build bin operation context from client config */
924→  private getBinContext(): binOps.BinOperationContext {
925→    return {
926→      ctx: this.ctx,
927→      userPrivateKey: this.config.vaultKeypair.privateKey,
928→      userPublicKey: this.config.vaultKeypair.publicKey,
929→      rootFolderKey: this.config.rootFolderKey,
930→      teeKeys: this.config.teeKeys,
931→    };
932→  }
933→
934→  /** Build share operation context from client config */
935→  private getShareContext(): shareOps.ShareOperationContext {
936→    return {
937→      ctx: this.ctx,
938→      userPrivateKey: this.config.vaultKeypair.privateKey,
939→      userPublicKey: this.config.vaultKeypair.publicKey,
940→    };
941→  }
942→
943→  // ---- Operation wrapper ----
944→
945→  /**
946→   * Wrap an async operation with event emission and error handling.
947→   *
948→   * Emits 'operation:start' before, 'operation:end' on success (with duration),
949→   * and 'error' on failure. Also calls the config callbacks if provided.
950→   */
951→  private async withOperation<T>(name: string, fn: () => Promise<T>): Promise<T> {
952→    const start = Date.now();
953→    this.notifySafely(() => this.config.onOperationStart?.(name));
954→    this.emitter.emit({ type: 'operation:start', operation: name });
955→
956→    try {
957→      const result = await fn();
958→      const durationMs = Date.now() - start;
959→      this.notifySafely(() => this.config.onOperationEnd?.(name));
960→      this.emitter.emit({ type: 'operation:end', operation: name, durationMs });
961→      return result;
962→    } catch (error) {
963→      this.notifySafely(() => this.config.onError?.(error as Error));
964→      this.emitter.emit({ type: 'error', operation: name, error: error as Error });
965→      throw error;
966→    }
967→  }
968→
969→  private notifySafely(fn: () => void): void {
970→    try {
971→      fn();
972→    } catch (err) {
973→      console.warn('[SDK] Lifecycle callback threw:', err);
974→    }
975→  }
976→}
977→

  1→/**
  2→ * Load Test Metrics Collection
  3→ *
  4→ * Collects per-operation latency, throughput, and error counts.
  5→ * Uses performance.now() for high-resolution timing.
  6→ */
  7→
  8→export interface OperationMetrics {
  9→  operation: string;
 10→  count: number;
 11→  errors: number;
 12→  latency: { p50: number; p95: number; p99: number; max: number; min: number; avg: number };
 13→  throughputOpsPerSec: number;
 14→  bytesTransferred?: number;
 15→}
 16→
 17→export interface OperationSample {
 18→  operation: string;
 19→  durationMs: number;
 20→  success: boolean;
 21→  bytes?: number;
 22→  timestamp: number;
 23→}
 24→
 25→export class MetricsCollector {
 26→  private samples: OperationSample[] = [];
 27→  private startTime = 0;
 28→  private endTime = 0;
 29→
 30→  start(): void {
 31→    this.startTime = performance.now();
 32→  }
 33→
 34→  stop(): void {
 35→    this.endTime = performance.now();
 36→  }
 37→
 38→  record(sample: OperationSample): void {
 39→    this.samples.push(sample);
 40→  }
 41→
 42→  /**
 43→   * Wrap an async operation to automatically record metrics.
 44→   */
 45→  async measure<T>(operation: string, fn: () => Promise<T>, bytes?: number): Promise<T> {
 46→    const start = performance.now();
 47→    try {
 48→      const result = await fn();
 49→      this.record({
 50→        operation,
 51→        durationMs: performance.now() - start,
 52→        success: true,
 53→        bytes,
 54→        timestamp: Date.now(),
 55→      });
 56→      return result;
 57→    } catch (err) {
 58→      this.record({
 59→        operation,
 60→        durationMs: performance.now() - start,
 61→        success: false,
 62→        bytes,
 63→        timestamp: Date.now(),
 64→      });
 65→      throw err;
 66→    }
 67→  }
 68→
 69→  /**
 70→   * Get aggregated metrics per operation type.
 71→   */
 72→  getMetrics(): OperationMetrics[] {
 73→    const elapsed = (this.endTime || performance.now()) - this.startTime;
 74→    const elapsedSec = elapsed / 1000;
 75→
 76→    const grouped = new Map<string, OperationSample[]>();
 77→    for (const s of this.samples) {
 78→      const list = grouped.get(s.operation) ?? [];
 79→      list.push(s);
 80→      grouped.set(s.operation, list);
 81→    }
 82→
 83→    const metrics: OperationMetrics[] = [];
 84→    for (const [op, samples] of grouped) {
 85→      const durations = samples.map((s) => s.durationMs).sort((a, b) => a - b);
 86→      const errors = samples.filter((s) => !s.success).length;
 87→      const totalBytes = samples.reduce((sum, s) => sum + (s.bytes ?? 0), 0);
 88→
 89→      metrics.push({
 90→        operation: op,
 91→        count: samples.length,
 92→        errors,
 93→        latency: {
 94→          min: durations[0] ?? 0,
 95→          avg: durations.reduce((a, b) => a + b, 0) / durations.length,
 96→          p50: percentile(durations, 0.5),
 97→          p95: percentile(durations, 0.95),
 98→          p99: percentile(durations, 0.99),
 99→          max: durations[durations.length - 1] ?? 0,
100→        },
101→        throughputOpsPerSec: elapsedSec > 0 ? samples.length / elapsedSec : 0,
102→        ...(totalBytes > 0 ? { bytesTransferred: totalBytes } : {}),
103→      });
104→    }
105→
106→    return metrics.sort((a, b) => a.operation.localeCompare(b.operation));
107→  }
108→
109→  /** Total samples collected */
110→  get totalSamples(): number {
111→    return this.samples.length;
112→  }
113→
114→  /** Total errors across all operations */
115→  get totalErrors(): number {
116→    return this.samples.filter((s) => !s.success).length;
117→  }
118→
119→  /** Raw samples (for JSON export) */
120→  getRawSamples(): OperationSample[] {
121→    return [...this.samples];
122→  }
123→}
124→
125→function percentile(sorted: number[], p: number): number {
126→  if (sorted.length === 0) return 0;
127→  const idx = Math.ceil(p * sorted.length) - 1;
128→  return sorted[Math.max(0, idx)];
129→}
130→

 1→/**
 2→ * Load Test Reporter
 3→ *
 4→ * Formats metrics into console table output and JSON export.
 5→ */
 6→
 7→import type { OperationMetrics } from './metrics';
 8→
 9→/**
10→ * Print a formatted summary table to console.
11→ */
12→export function printSummary(
13→  scenarioName: string,
14→  metrics: OperationMetrics[],
15→  totalDurationMs: number,
16→  clientCount: number
17→): void {
18→  const totalOps = metrics.reduce((sum, m) => sum + m.count, 0);
19→  const totalErrors = metrics.reduce((sum, m) => sum + m.errors, 0);
20→  const totalBytes = metrics.reduce((sum, m) => sum + (m.bytesTransferred ?? 0), 0);
21→
22→  console.log(`\n${'='.repeat(80)}`);
23→  console.log(`LOAD TEST: ${scenarioName}`);
24→  console.log(`${'='.repeat(80)}`);
25→  console.log(`Clients:     ${clientCount}`);
26→  console.log(`Duration:    ${(totalDurationMs / 1000).toFixed(1)}s`);
27→  console.log(`Total ops:   ${totalOps} (${totalErrors} errors)`);
28→  console.log(`Throughput:  ${(totalOps / (totalDurationMs / 1000)).toFixed(2)} ops/sec`);
29→  if (totalBytes > 0) {
30→    console.log(`Data:        ${formatBytes(totalBytes)}`);
31→  }
32→  console.log(`${'─'.repeat(80)}`);
33→
34→  // Table header
35→  console.log(
36→    padRight('Operation', 22) +
37→      padRight('Count', 8) +
38→      padRight('Errors', 8) +
39→      padRight('p50', 10) +
40→      padRight('p95', 10) +
41→      padRight('p99', 10) +
42→      padRight('Max', 10)
43→  );
44→  console.log('─'.repeat(80));
45→
46→  for (const m of metrics) {
47→    console.log(
48→      padRight(m.operation, 22) +
49→        padRight(String(m.count), 8) +
50→        padRight(String(m.errors), 8) +
51→        padRight(fmtMs(m.latency.p50), 10) +
52→        padRight(fmtMs(m.latency.p95), 10) +
53→        padRight(fmtMs(m.latency.p99), 10) +
54→        padRight(fmtMs(m.latency.max), 10)
55→    );
56→  }
57→
58→  console.log(`${'='.repeat(80)}\n`);
59→}
60→
61→/**
62→ * Export metrics as JSON (for CI artifact upload).
63→ */
64→export function toJsonReport(
65→  scenarioName: string,
66→  metrics: OperationMetrics[],
67→  totalDurationMs: number,
68→  clientCount: number
69→): string {
70→  return JSON.stringify(
71→    {
72→      scenario: scenarioName,
73→      clientCount,
74→      totalDurationMs,
75→      totalOps: metrics.reduce((sum, m) => sum + m.count, 0),
76→      totalErrors: metrics.reduce((sum, m) => sum + m.errors, 0),
77→      operations: metrics,
78→      timestamp: new Date().toISOString(),
79→    },
80→    null,
81→    2
82→  );
83→}
84→
85→function padRight(str: string, len: number): string {
86→  return str.padEnd(len);
87→}
88→
89→function fmtMs(ms: number): string {
90→  if (ms < 1000) return `${Math.round(ms)}ms`;
91→  return `${(ms / 1000).toFixed(1)}s`;
92→}
93→
94→function formatBytes(bytes: number): string {
95→  if (bytes < 1024) return `${bytes}B`;
96→  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)}KB`;
97→  return `${(bytes / (1024 * 1024)).toFixed(1)}MB`;
98→}
