 1→/**
 2→ * IPNS Publish Storm Scenario
 3→ *
 4→ * N clients performing rapid folder mutations, each triggering IPNS publish.
 5→ * Tests IPNS publish contention — the known system bottleneck.
 6→ */
 7→
 8→import { describe, it, afterAll } from 'vitest';
 9→import { createClientPool, destroyClientPool, type PoolClient } from '../harness/client-pool';
10→import { MetricsCollector } from '../harness/metrics';
11→import { printSummary, toJsonReport } from '../harness/reporter';
12→import { runFolderWorkload } from '../workloads/folder-workload';
13→
14→const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '20', 10);
15→const CYCLES_PER_CLIENT = 50;
16→
17→describe('IPNS Publish Storm', () => {
18→  let pool: PoolClient[] = [];
19→
20→  afterAll(async () => {
21→    await destroyClientPool(pool);
22→  });
23→
24→  it(`${NUM_CLIENTS} clients × ${CYCLES_PER_CLIENT} folder create-rename-delete cycles`, async () => {
25→    pool = await createClientPool({
26→      clientCount: NUM_CLIENTS,
27→      label: 'ipns-storm',
28→    });
29→
30→    // Run all client workloads concurrently
31→    const results = await Promise.allSettled(
32→      pool.map((pc) => {
33→        pc.metrics.start();
34→        return runFolderWorkload(pc, { cycles: CYCLES_PER_CLIENT }).finally(() =>
35→          pc.metrics.stop()
36→        );
37→      })
38→    );
39→
40→    // Aggregate
41→    const allMetrics = new MetricsCollector();
42→    allMetrics.start();
43→    for (const pc of pool) {
44→      for (const sample of pc.metrics.getRawSamples()) {
45→        allMetrics.record(sample);
46→      }
47→    }
48→    allMetrics.stop();
49→
50→    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
51→    console.log(`\nClients completed: ${succeeded}/${pool.length}`);
52→
53→    const metrics = allMetrics.getMetrics();
54→    const samples = pool.flatMap((pc) => pc.metrics.getRawSamples());
55→    const totalDuration =
56→      samples.length > 0
57→        ? Math.max(...samples.map((s) => s.timestamp)) -
58→          Math.min(...samples.map((s) => s.timestamp))
59→        : 0;
60→
61→    printSummary('IPNS Publish Storm', metrics, totalDuration, pool.length);
62→    console.log(
63→      '\nJSON Report:\n' + toJsonReport('ipns-publish-storm', metrics, totalDuration, pool.length)
64→    );
65→  });
66→});
