 1→/**
 2→ * @cipherbox/sdk
 3→ *
 4→ * Stateful SDK client for CipherBox. Orchestrates folder CRUD, file upload/download,
 5→ * bin operations, and share operations with internal state management and
 6→ * event-driven change notification.
 7→ *
 8→ * Usage:
 9→ * ```typescript
10→ * import { CipherBoxClient, type CipherBoxClientConfig } from '@cipherbox/sdk';
11→ *
12→ * const client = new CipherBoxClient({
13→ *   apiUrl: 'https://api.cipherbox.cc',
14→ *   getAccessToken: () => authStore.getAccessToken(),
15→ *   vaultKeypair: { publicKey, privateKey },
16→ *   rootIpnsName: 'k51...',
17→ *   rootFolderKey: decryptedRootKey,
18→ * });
19→ *
20→ * // Subscribe to events
21→ * const unsub = client.on((event) => {
22→ *   if (event.type === 'folder:updated') {
23→ *     zustandStore.updateFolder(event.folderId, event.children);
24→ *   }
25→ * });
26→ *
27→ * // Load root folder
28→ * await client.loadFolder(rootIpnsName, rootFolderKey, rootIpnsKeypair);
29→ *
30→ * // Cleanup
31→ * unsub();
32→ * client.destroy();
33→ * ```
34→ */
35→
36→// Main client
37→export { CipherBoxClient, BinNotLoadedError } from './client';
