 1→/**
 2→ * File Upload/Download Workload
 3→ *
 4→ * Parameterized workload that uploads and downloads files of varying sizes.
 5→ */
 6→
 7→import type { PoolClient } from '../harness/client-pool';
 8→
 9→export interface FileWorkloadOptions {
10→  /** Number of files to upload */
11→  fileCount: number;
12→  /** Min file size in bytes */
13→  minSize: number;
14→  /** Max file size in bytes */
15→  maxSize: number;
16→  /** Whether to verify downloads after upload */
17→  verifyDownloads: boolean;
18→}
19→
20→/**
21→ * Run a file upload workload on a single client.
22→ */
23→export async function runFileWorkload(pc: PoolClient, opts: FileWorkloadOptions): Promise<void> {
24→  const { fileCount, minSize, maxSize, verifyDownloads } = opts;
25→  const { client, rootIpnsName, rootFolderKey, metrics } = pc;
26→
27→  for (let i = 0; i < fileCount; i++) {
28→    const size = minSize + Math.floor(Math.random() * (maxSize - minSize));
29→    const data = new Uint8Array(size);
30→    crypto.getRandomValues(data);
31→    const fileName = `load-${pc.id}-file-${i}-${size}b.bin`;
32→
33→    // Upload
34→    await metrics.measure(
35→      'uploadFile',
36→      () => client.uploadFile(rootIpnsName, data, fileName, 'application/octet-stream'),
37→      size
38→    );
39→
40→    // Optionally download and verify
41→    if (verifyDownloads) {
42→      const folder = (client as any).folderTree.get(rootIpnsName);
43→      const child = folder?.children.find((c: any) => c.name === fileName);
44→      if (child?.fileMetaIpnsName) {
45→        const downloaded = await metrics.measure(
46→          'downloadFile',
47→          () => client.downloadFromIpns(child.fileMetaIpnsName, rootFolderKey),
48→          size
49→        );
50→        if (downloaded.length !== data.length) {
51→          throw new Error(
52→            `Size mismatch: uploaded ${data.length}, downloaded ${downloaded.length}`
53→          );
54→        }
55→      }
56→    }
57→  }
58→}
