import { Injectable, ExecutionContext } from '@nestjs/common';
import { ThrottlerGuard } from '@nestjs/throttler';
import { ConfigService } from '@nestjs/config';

/**
 * Extends the default ThrottlerGuard with a bypass header mechanism.
 *
 * When `THROTTLE_BYPASS_SECRET` is configured and the request includes
 * a matching `X-Throttle-Bypass` header, rate limiting is skipped.
 * This allows SDK E2E and load tests to run against staging without
 * hitting 429s, while keeping production rate limits enforced
 * (production simply never sets the secret).
 *
 * Usage:
 *   Replace `@UseGuards(ThrottlerGuard)` with `@UseGuards(BypassableThrottlerGuard)`
 *   in controllers.
 *
 * Security:
 *   - The secret is never set in production — bypass is impossible
 *   - HMAC comparison prevents timing attacks
 *   - The bypass header is ignored if the secret env var is unset
 */
@Injectable()
export class BypassableThrottlerGuard extends ThrottlerGuard {
  private bypassSecret: string | undefined;

  constructor(
    ...args: ConstructorParameters<typeof ThrottlerGuard>
  ) {
    super(...args);
    // Inject ConfigService manually since ThrottlerGuard doesn't use standard DI for config
    // The secret is read once at construction time
  }

  /** Called by NestJS to set module ref — we use it to grab ConfigService */
  onModuleInit(): void {
    const moduleRef = (this as any).options?.[0]?.moduleRef ?? (this as any).moduleRef;
    try {
      // ThrottlerGuard receives the module ref via NestJS lifecycle
      const configService = (this as any).reflector
        ? undefined
        : undefined;
      // Fallback: read directly from process.env (ConfigService may not be available in guard constructor)
      this.bypassSecret = process.env.THROTTLE_BYPASS_SECRET;
    } catch {
      this.bypassSecret = process.env.THROTTLE_BYPASS_SECRET;
    }
  }

  async canActivate(context: ExecutionContext): Promise<boolean> {
    // Lazy-init: read secret on first call if not yet set
    if (this.bypassSecret === undefined) {
      this.bypassSecret = process.env.THROTTLE_BYPASS_SECRET || '';
    }

    // If bypass secret is configured and header matches, skip throttling
    if (this.bypassSecret) {
      const request = context.switchToHttp().getRequest();
      const headerValue = request.headers['x-throttle-bypass'];
      if (headerValue && headerValue === this.bypassSecret) {
        return true;
      }
    }

    // Fall through to normal rate limiting
    return super.canActivate(context);
  }
}

