import {
  Controller,
  Post,
  Get,
  Delete,
  Patch,
  Body,
  Param,
  Query,
  UseGuards,
  Request,
  ParseUUIDPipe,
  HttpCode,
  HttpStatus,
  BadRequestException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth, ApiQuery } from '@nestjs/swagger';
import { ThrottlerGuard } from '@nestjs/throttler';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { SharesService } from './shares.service';
import { CreateShareDto } from './dto/create-share.dto';
import { AddShareKeysDto } from './dto/share-key.dto';
import { UpdateEncryptedKeyDto } from './dto/update-encrypted-key.dto';
import {
  PaginationQueryDto,
  PaginatedReceivedSharesDto,
  PaginatedSentSharesDto,
} from './dto/pagination.dto';
import {
  CreateShareResponseDto,
  PendingRotationResponseDto,
  ShareKeyResponseDto,
} from './dto/share-response.dto';
import { LookupUserResponseDto } from './dto/lookup-user-response.dto';
import { RequestWithUser } from '../common/types';

@ApiTags('shares')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, ThrottlerGuard)
@Controller('shares')
export class SharesController {
  constructor(private readonly sharesService: SharesService) {}

  @Post()
  @ApiOperation({
    summary: 'Create a share',
    description:
      'Share an encrypted folder or file with another user. ' +
      'The encryptedKey is the item key re-wrapped for the recipient via ECIES.',
  })
  @ApiResponse({ status: 201, description: 'Share created', type: CreateShareResponseDto })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  @ApiResponse({ status: 404, description: 'Recipient not found' })
  @ApiResponse({ status: 409, description: 'Share already exists or self-share' })
  async createShare(
    @Request() req: RequestWithUser,
    @Body() dto: CreateShareDto
  ): Promise<{
    shareId: string;
    itemType: string;
    ipnsName: string;
    itemName: string;
    encryptedKey: string;
    createdAt: Date;
  }> {
    const share = await this.sharesService.createShare(req.user.id, dto);
    return {
      shareId: share.id,
      itemType: share.itemType,
      ipnsName: share.ipnsName,
      itemName: share.itemName,
      encryptedKey: share.encryptedKey.toString('hex'),
      createdAt: share.createdAt,
    };
  }

  @Get('received')
  @ApiOperation({
    summary: 'List received shares',
    description: 'Get active, non-hidden shares received by the authenticated user (paginated).',
  })
  @ApiResponse({
    status: 200,
    description: 'Paginated list of received shares',
    type: PaginatedReceivedSharesDto,
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async getReceivedShares(
    @Request() req: RequestWithUser,
    @Query() pagination: PaginationQueryDto
  ): Promise<PaginatedReceivedSharesDto> {
    const { shares, total } = await this.sharesService.getReceivedShares(
      req.user.id,
      pagination.limit,
      pagination.offset
    );
    return {
      shares: shares.map((s) => ({
        shareId: s.id,
        sharerPublicKey: s.sharer.publicKey,
        itemType: s.itemType,
        ipnsName: s.ipnsName,
        itemName: s.itemName,
        encryptedKey: s.encryptedKey.toString('hex'),
        createdAt: s.createdAt,
      })),
      total,
    };
  }

  @Get('sent')
  @ApiOperation({
    summary: 'List sent shares',
    description: 'Get active shares created by the authenticated user (paginated).',
  })
  @ApiResponse({
    status: 200,
    description: 'Paginated list of sent shares',
    type: PaginatedSentSharesDto,
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async getSentShares(
    @Request() req: RequestWithUser,
    @Query() pagination: PaginationQueryDto
  ): Promise<PaginatedSentSharesDto> {
    const { shares, total } = await this.sharesService.getSentShares(
      req.user.id,
      pagination.limit,
      pagination.offset
    );
    return {
      shares: shares.map((s) => ({
        shareId: s.id,
        recipientPublicKey: s.recipient.publicKey,
        itemType: s.itemType,
        ipnsName: s.ipnsName,
        itemName: s.itemName,
        createdAt: s.createdAt,
      })),
      total,
    };
  }

  @Get('lookup')
  @ApiOperation({
    summary: 'Look up user by public key',
    description: 'Verify a public key belongs to a registered CipherBox user.',
  })
  @ApiQuery({
    name: 'publicKey',
    description: 'Uncompressed secp256k1 public key (0x04...)',
    required: true,
  })
  @ApiResponse({ status: 200, description: 'Lookup result', type: LookupUserResponseDto })
  @ApiResponse({ status: 400, description: 'Invalid public key format' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async lookupUser(@Query('publicKey') publicKey: string): Promise<LookupUserResponseDto> {
    if (!publicKey || !/^0x04[0-9a-fA-F]{128}$/.test(publicKey)) {
      throw new BadRequestException(
        'Invalid public key format. Expected uncompressed secp256k1 key: 0x04 + 128 hex chars'
      );
    }

    const exists = await this.sharesService.lookupUserByPublicKey(publicKey);
    return { exists };
  }

  @Get('pending-rotations')
  @ApiOperation({
    summary: 'Get pending rotations',
    description:
      'Get shares that have been revoked but not yet key-rotated. ' +
      'Used by the client to detect lazy rotation needs before folder modification.',
  })
  @ApiResponse({
    status: 200,
    description: 'List of revoked shares pending rotation',
    type: [PendingRotationResponseDto],
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async getPendingRotations(@Request() req: RequestWithUser): Promise<
    Array<{
      shareId: string;
      recipientPublicKey: string;
      itemType: string;
      ipnsName: string;
      itemName: string;
      revokedAt: Date;
    }>
  > {
    const shares = await this.sharesService.getPendingRotations(req.user.id);
    return shares.map((s) => ({
      shareId: s.id,
      recipientPublicKey: s.recipient.publicKey,
      itemType: s.itemType,
      ipnsName: s.ipnsName,
      itemName: s.itemName,
      revokedAt: s.revokedAt!,
    }));
  }

  @Get(':shareId/keys')
  @ApiOperation({
    summary: 'Get share keys',
    description: 'Get all re-wrapped child keys for a share. Accessible by sharer or recipient.',
  })
  @ApiResponse({ status: 200, description: 'List of share keys', type: [ShareKeyResponseDto] })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  @ApiResponse({ status: 403, description: 'Not authorized to access this share' })
  @ApiResponse({ status: 404, description: 'Share not found' })
  async getShareKeys(
    @Request() req: RequestWithUser,
    @Param('shareId', ParseUUIDPipe) shareId: string
  ): Promise<
    Array<{
      keyType: string;
      itemId: string;
      encryptedKey: string;
    }>
  > {
    const keys = await this.sharesService.getShareKeys(shareId, req.user.id);
    return keys.map((k) => ({
      keyType: k.keyType,
      itemId: k.itemId,
      encryptedKey: k.encryptedKey.toString('hex'),
    }));
  }

  @Post(':shareId/keys')
  @ApiOperation({
    summary: 'Add share keys',
    description: 'Add re-wrapped child keys to an existing share. Only the sharer can add keys.',
  })
  @ApiResponse({ status: 201, description: 'Keys added' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  @ApiResponse({ status: 403, description: 'Only the sharer can add keys' })
  @ApiResponse({ status: 404, description: 'Share not found' })
  async addShareKeys(
    @Request() req: RequestWithUser,
    @Param('shareId', ParseUUIDPipe) shareId: string,
    @Body() dto: AddShareKeysDto
  ): Promise<void> {
    await this.sharesService.addShareKeys(shareId, req.user.id, dto);
  }

  @Delete(':shareId')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiOperation({
    summary: 'Revoke a share',
    description:
      'Soft-delete a share by setting revokedAt. ' +
      'Only the sharer can revoke. Keys are kept for lazy rotation.',
  })
  @ApiResponse({ status: 204, description: 'Share revoked' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  @ApiResponse({ status: 403, description: 'Only the sharer can revoke' })
  @ApiResponse({ status: 404, description: 'Share not found' })
  async revokeShare(
    @Request() req: RequestWithUser,
    @Param('shareId', ParseUUIDPipe) shareId: string
  ): Promise<void> {
    await this.sharesService.revokeShare(shareId, req.user.id);
  }

  @Patch(':shareId/hide')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiOperation({
    summary: 'Hide a share',
    description: 'Mark a share as hidden by the recipient. Only the recipient can hide.',
  })
  @ApiResponse({ status: 204, description: 'Share hidden' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  @ApiResponse({ status: 403, description: 'Only the recipient can hide' })
  @ApiResponse({ status: 404, description: 'Share not found' })
  async hideShare(
    @Request() req: RequestWithUser,
    @Param('shareId', ParseUUIDPipe) shareId: string
  ): Promise<void> {
    await this.sharesService.hideShare(shareId, req.user.id);
  }

  @Patch(':shareId/encrypted-key')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiOperation({
    summary: 'Update share encrypted key',
    description:
      'Update the encrypted key on an existing share after lazy key rotation. ' +
      'Only the sharer can update the key.',
  })
  @ApiResponse({ status: 204, description: 'Encrypted key updated' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  @ApiResponse({ status: 403, description: 'Only the sharer can update' })
  @ApiResponse({ status: 404, description: 'Share not found' })
  async updateShareEncryptedKey(
    @Request() req: RequestWithUser,
    @Param('shareId', ParseUUIDPipe) shareId: string,
    @Body() dto: UpdateEncryptedKeyDto
  ): Promise<void> {
    await this.sharesService.updateShareEncryptedKey(shareId, req.user.id, dto.encryptedKey);
  }

  @Delete(':shareId/complete-rotation')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiOperation({
    summary: 'Complete key rotation',
    description:
      'Hard-delete a revoked share after the sharer has rotated the folder key. ' +
      'Called after the client performs lazy key rotation.',
  })
  @ApiResponse({ status: 204, description: 'Share hard-deleted after rotation' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  @ApiResponse({ status: 403, description: 'Only the sharer can complete rotation' })
  @ApiResponse({ status: 404, description: 'Share not found' })
  @ApiResponse({ status: 409, description: 'Share has not been revoked' })
  async completeRotation(
    @Request() req: RequestWithUser,
    @Param('shareId', ParseUUIDPipe) shareId: string
  ): Promise<void> {
    await this.sharesService.completeRotation(shareId, req.user.id);
  }
}

import {
  Controller,
  Post,
  Get,
  Delete,
  Body,
  Param,
  Query,
  UseGuards,
  Request,
  ParseUUIDPipe,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth, ApiQuery } from '@nestjs/swagger';
import { ThrottlerGuard } from '@nestjs/throttler';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { ShareInviteService } from './share-invite.service';
import { CreateInviteDto } from './dto/create-invite.dto';
import { InviteResponseDto } from './dto/invite-response.dto';
import { RequestWithUser } from '../common/types';

/**
 * Authenticated invite management controller at /shares/invites prefix.
 * All endpoints require authentication (class-level JwtAuthGuard).
 */
@ApiTags('share-invites')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, ThrottlerGuard)
@Controller('shares/invites')
export class ShareInvitesController {
  constructor(private readonly shareInviteService: ShareInviteService) {}

  /**
   * Create a new invite link for sharing a file or folder.
   * Returns the invite token for URL construction on the client.
   */
  @Post()
  @ApiOperation({
    summary: 'Create an invite link',
    description:
      'Create a new invite link with the item key wrapped by an ephemeral public key. ' +
      'Returns the invite token for URL construction. Default expiry: 7 days.',
  })
  @ApiResponse({
    status: 201,
    description: 'Invite created',
    type: InviteResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async createInvite(
    @Request() req: RequestWithUser,
    @Body() dto: CreateInviteDto
  ): Promise<{
    id: string;
    token: string;
    itemType: string;
    ipnsName: string;
    itemName: string;
    status: string;
    expiresAt: Date;
    createdAt: Date;
  }> {
    const invite = await this.shareInviteService.createInvite(req.user.id, dto);
    return {
      id: invite.id,
      token: invite.token,
      itemType: invite.itemType,
      ipnsName: invite.ipnsName,
      itemName: invite.itemName,
      status: invite.status,
      expiresAt: invite.expiresAt,
      createdAt: invite.createdAt,
    };
  }

  /**
   * List active (unclaimed, unexpired) invites for a specific item.
   * Requires ipnsName query parameter.
   */
  @Get()
  @ApiOperation({
    summary: 'List active invites for an item',
    description:
      'Get all active (unclaimed, unexpired) invite links created by the authenticated user ' +
      'for the specified item. Expired invites are auto-cleaned.',
  })
  @ApiQuery({
    name: 'ipnsName',
    description: 'IPNS name of the item to list invites for',
    required: true,
  })
  @ApiResponse({
    status: 200,
    description: 'List of active invites',
    type: [InviteResponseDto],
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async listInvites(
    @Request() req: RequestWithUser,
    @Query('ipnsName') ipnsName: string
  ): Promise<
    Array<{
      id: string;
      token: string;
      itemType: string;
      ipnsName: string;
      itemName: string;
      status: string;
      expiresAt: Date;
      createdAt: Date;
    }>
  > {
    const invites = await this.shareInviteService.getInvitesForItem(req.user.id, ipnsName);
    return invites.map((inv) => ({
      id: inv.id,
      token: inv.token,
      itemType: inv.itemType,
      ipnsName: inv.ipnsName,
      itemName: inv.itemName,
      status: inv.status,
      expiresAt: inv.expiresAt,
      createdAt: inv.createdAt,
    }));
  }

  /**
   * Revoke an active invite link.
   * Only the sharer can revoke. Already-claimed shares are unaffected.
   */
  @Delete(':inviteId')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiOperation({
    summary: 'Revoke an invite link',
    description:
      'Revoke an active invite link. Only the original sharer can revoke. ' +
      'Already-claimed shares persist independently.',
  })
  @ApiResponse({ status: 204, description: 'Invite revoked' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  @ApiResponse({ status: 403, description: 'Only the sharer can revoke' })
  @ApiResponse({ status: 404, description: 'Invite not found' })
  async revokeInvite(
    @Request() req: RequestWithUser,
    @Param('inviteId', ParseUUIDPipe) inviteId: string
  ): Promise<void> {
    await this.shareInviteService.revokeInvite(inviteId, req.user.id);
  }
}

import {
  Controller,
  Get,
  Post,
  Body,
  Param,
  UseGuards,
  Request,
  NotFoundException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth, ApiParam } from '@nestjs/swagger';
import { ThrottlerGuard } from '@nestjs/throttler';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { ShareInviteService } from './share-invite.service';
import { ClaimInviteDto } from './dto/claim-invite.dto';
import {
  InviteStatusResponseDto,
  InviteDataResponseDto,
  ClaimInviteResponseDto,
} from './dto/invite-response.dto';
import { RequestWithUser } from '../common/types';
import { ParseTokenPipe } from '../common/pipes/parse-token.pipe';

/**
 * Public-facing invite controller at /invites prefix.
 * NO class-level auth guard -- individual endpoints opt in.
 */
@ApiTags('invites')
@Controller('invites')
export class InvitesController {
  constructor(private readonly shareInviteService: ShareInviteService) {}

  /**
   * PUBLIC: No auth required -- returns only the invite status.
   * Used by the invite landing page before the recipient logs in.
   * Opaque: no file name, no sharer identity.
   */
  @Get(':token')
  @UseGuards(ThrottlerGuard)
  @ApiOperation({
    summary: 'Get invite status (public)',
    description:
      'Check the status of an invite link. Returns only status -- ' +
      'no file name or sharer identity is revealed before authentication.',
  })
  @ApiParam({ name: 'token', description: 'Invite token (URL-safe base64)' })
  @ApiResponse({
    status: 200,
    description: 'Invite status',
    type: InviteStatusResponseDto,
  })
  @ApiResponse({ status: 404, description: 'Invite not found or expired' })
  async getInviteStatus(
    @Param('token', ParseTokenPipe) token: string
  ): Promise<{ status: string }> {
    const result = await this.shareInviteService.getInviteStatus(token);
    if (!result || result.status !== 'active') {
      throw new NotFoundException();
    }
    return { status: 'active' };
  }

  /**
   * AUTHENTICATED: Returns full invite data needed for the claim flow.
   * The client uses the encrypted key ciphertext to unwrap with the
   * ephemeral private key (from URL fragment) and re-wrap with their own key.
   */
  @Get(':token/data')
  @UseGuards(JwtAuthGuard, ThrottlerGuard)
  @ApiBearerAuth()
  @ApiOperation({
    summary: 'Get invite data for claim flow (authenticated)',
    description:
      'Fetch full invite data including encrypted key ciphertext. ' +
      'Requires authentication. Used by the client claim flow.',
  })
  @ApiParam({ name: 'token', description: 'Invite token (URL-safe base64)' })
  @ApiResponse({
    status: 200,
    description: 'Full invite data for claim flow',
    type: InviteDataResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  @ApiResponse({ status: 404, description: 'Invite not found or expired' })
  async getInviteData(@Param('token', ParseTokenPipe) token: string): Promise<{
    status: string;
    encryptedKey: string;
    encryptedChildKeys: Array<{
      keyType: 'file' | 'folder';
      itemId: string;
      encryptedKey: string;
    }> | null;
    itemType: string;
    ipnsName: string;
    itemName: string;
  }> {
    const invite = await this.shareInviteService.getInviteForClaim(token);

    if (!invite) {
      throw new NotFoundException('Invite not found or expired');
    }

    return {
      status: invite.status,
      encryptedKey: invite.encryptedKey.toString('hex'),
      encryptedChildKeys: invite.encryptedChildKeys,
      itemType: invite.itemType,
      ipnsName: invite.ipnsName,
      itemName: invite.itemName,
    };
  }

  /**
   * AUTHENTICATED: Claim an invite by providing re-wrapped keys.
   * Creates Share + ShareKey records via the existing sharing infrastructure.
   */
  @Post(':token/claim')
  @UseGuards(JwtAuthGuard, ThrottlerGuard)
  @ApiBearerAuth()
  @ApiOperation({
    summary: 'Claim an invite link',
    description:
      'Claim an invite by providing the item key re-wrapped for the recipient. ' +
      'Creates Share and ShareKey records. Single-claim enforced atomically.',
  })
  @ApiParam({ name: 'token', description: 'Invite token (URL-safe base64)' })
  @ApiResponse({
    status: 201,
    description: 'Invite claimed successfully',
    type: ClaimInviteResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  @ApiResponse({ status: 404, description: 'Invite not found or expired' })
  @ApiResponse({ status: 409, description: 'Invite already claimed or self-claim' })
  async claimInvite(
    @Request() req: RequestWithUser,
    @Param('token', ParseTokenPipe) token: string,
    @Body() dto: ClaimInviteDto
  ): Promise<{ shareId: string }> {
    return this.shareInviteService.claimInvite(token, req.user.id, dto);
  }
}

import {
  Controller,
  Post,
  Get,
  Delete,
  Body,
  HttpCode,
  HttpStatus,
  UseGuards,
  Request,
  Res,
  Req,
  UnauthorizedException,
  BadRequestException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth } from '@nestjs/swagger';
import { Response, Request as ExpressRequest } from 'express';
import { AuthService } from './auth.service';
import { AuthMethodService } from './services/auth-method.service';
import { TestAuthService } from './services/test-auth.service';
import { LoginDto, LoginResponseDto } from './dto/login.dto';
import { TokenResponseDto, DesktopRefreshDto, LogoutResponseDto } from './dto/token.dto';
import { TestLoginDto, TestLoginResponseDto } from './dto/test-login.dto';
import {
  LinkMethodDto,
  AuthMethodResponseDto,
  UnlinkMethodDto,
  UnlinkMethodResponseDto,
} from './dto/link-method.dto';
import { DeleteAccountDto, DeleteAccountResponseDto } from './dto/delete-account.dto';
import { ThrottlerGuard } from '@nestjs/throttler';
import { Throttle } from '@nestjs/throttler';
import { JwtAuthGuard } from './guards/jwt-auth.guard';
import { User } from './entities/user.entity';
import { MetricsService } from '../metrics/metrics.service';

interface RequestWithUser extends Request {
  user: User;
}

// Cookie configuration
const REFRESH_TOKEN_COOKIE_OPTIONS = {
  httpOnly: true,
  secure: process.env.NODE_ENV === 'production',
  sameSite: 'lax' as const,
  maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
  path: '/auth', // Only sent to auth endpoints
};

@ApiTags('Auth')
@Controller('auth')
export class AuthController {
  constructor(
    private authService: AuthService,
    private authMethodService: AuthMethodService,
    private testAuthService: TestAuthService,
    private readonly metricsService: MetricsService
  ) {}

  @Post('login')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ThrottlerGuard)
  @Throttle({ default: { limit: 10, ttl: 60000 } })
  @ApiOperation({ summary: 'Authenticate user with Web3Auth ID token' })
  @ApiResponse({
    status: 200,
    description: 'Successfully authenticated',
    type: LoginResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Invalid Web3Auth token' })
  async login(
    @Body() loginDto: LoginDto,
    @Req() req: ExpressRequest,
    @Res({ passthrough: true }) res: Response
  ): Promise<LoginResponseDto> {
    const result = await this.authService.login(loginDto);
    this.metricsService.authLogins.inc({
      method: 'web3auth',
      new_user: String(result.isNewUser),
    });
    const isDesktop = req.headers['x-client-type'] === 'desktop';

    if (isDesktop) {
      // Desktop clients: return refreshToken in response body (no cookie)
      // For scoped temp auth (REQUIRED_SHARE), refreshToken is empty string → omitted
      return {
        accessToken: result.accessToken,
        refreshToken: result.refreshToken || undefined,
        isNewUser: result.isNewUser,
      };
    }

    // Web clients: set refresh token in HTTP-only cookie (skip for scoped temp auth)
    if (result.refreshToken) {
      res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);
    }

    return {
      accessToken: result.accessToken,
      isNewUser: result.isNewUser,
    };
  }

  @Post('refresh')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Refresh access token using HTTP-only refresh token cookie' })
  @ApiResponse({
    status: 200,
    description: 'Tokens refreshed successfully',
    type: TokenResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Invalid or expired refresh token' })
  async refresh(
    @Req() req: ExpressRequest,
    @Body() body: DesktopRefreshDto,
    @Res({ passthrough: true }) res: Response
  ): Promise<TokenResponseDto> {
    const isDesktop = req.headers['x-client-type'] === 'desktop';

    let refreshToken: string | undefined;

    if (isDesktop) {
      // Desktop clients: read refresh token from request body
      refreshToken = body?.refreshToken;
    } else {
      // Web clients: read refresh token from cookie
      refreshToken = req.cookies?.['refresh_token'];
    }

    if (!refreshToken) {
      throw new UnauthorizedException('No refresh token');
    }

    const result = await this.authService.refreshByToken(refreshToken);

    if (isDesktop) {
      // Desktop clients: return new refreshToken in response body (no cookie)
      return {
        accessToken: result.accessToken,
        refreshToken: result.refreshToken,
        email: result.email,
      };
    }

    // Web clients: set new refresh token in HTTP-only cookie (rotation)
    res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);

    return {
      accessToken: result.accessToken,
      email: result.email,
    };
  }

  @Post('logout')
  @HttpCode(HttpStatus.OK)
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Logout user and invalidate all refresh tokens' })
  @ApiResponse({
    status: 200,
    description: 'Successfully logged out',
    type: LogoutResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async logout(
    @Request() req: RequestWithUser,
    @Res({ passthrough: true }) res: Response
  ): Promise<LogoutResponseDto> {
    const isDesktop = (req as unknown as ExpressRequest).headers['x-client-type'] === 'desktop';

    if (!isDesktop) {
      // Web clients: clear the refresh token cookie
      res.clearCookie('refresh_token', { path: '/auth' });
    }

    return this.authService.logout(req.user.id);
  }

  @Delete('account')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ThrottlerGuard)
  @Throttle({ default: { limit: 3, ttl: 60000 } })
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Permanently delete user account and all associated data' })
  @ApiResponse({
    status: 200,
    description: 'Account deleted successfully',
    type: DeleteAccountResponseDto,
  })
  @ApiResponse({ status: 400, description: 'Invalid confirmation or account not found' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async deleteAccount(
    @Request() req: RequestWithUser,
    @Body() dto: DeleteAccountDto,
    @Res({ passthrough: true }) res: Response
  ): Promise<DeleteAccountResponseDto> {
    if (dto.confirmation !== 'DELETE') {
      throw new BadRequestException('Confirmation must be the string "DELETE"');
    }
    const result = await this.authService.deleteAccount(req.user.id);
    const isDesktop = (req as unknown as ExpressRequest).headers['x-client-type'] === 'desktop';
    if (!isDesktop) {
      res.clearCookie('refresh_token', { path: '/auth' });
    }
    return result;
  }

  @Get('methods')
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Get all linked auth methods for the current user' })
  @ApiResponse({
    status: 200,
    description: 'List of linked auth methods',
    type: [AuthMethodResponseDto],
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async getMethods(@Request() req: RequestWithUser): Promise<AuthMethodResponseDto[]> {
    return this.authMethodService.getLinkedMethods(req.user.id);
  }

  @Post('link')
  @HttpCode(HttpStatus.OK)
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Link a new auth method to the current user account' })
  @ApiResponse({
    status: 200,
    description: 'Auth method linked successfully, returns updated list of methods',
    type: [AuthMethodResponseDto],
  })
  @ApiResponse({ status: 400, description: 'Auth method already linked or publicKey mismatch' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async linkMethod(
    @Request() req: RequestWithUser,
    @Body() linkDto: LinkMethodDto
  ): Promise<AuthMethodResponseDto[]> {
    return this.authMethodService.linkMethod(req.user.id, linkDto);
  }

  @Post('unlink')
  @HttpCode(HttpStatus.OK)
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Unlink an auth method from the current user account' })
  @ApiResponse({
    status: 200,
    description: 'Auth method unlinked successfully',
    type: UnlinkMethodResponseDto,
  })
  @ApiResponse({ status: 400, description: 'Cannot unlink last auth method or method not found' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async unlinkMethod(
    @Request() req: RequestWithUser,
    @Body() unlinkDto: UnlinkMethodDto
  ): Promise<UnlinkMethodResponseDto> {
    await this.authMethodService.unlinkMethod(req.user.id, unlinkDto.methodId);
    return { success: true };
  }

  @Post('test-login')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ThrottlerGuard)
  @Throttle({ default: { limit: 5, ttl: 900000 } })
  @ApiOperation({
    summary: 'Test-only login bypassing Core Kit (requires TEST_LOGIN_SECRET)',
  })
  @ApiResponse({
    status: 200,
    description: 'Test login successful',
    type: TestLoginResponseDto,
  })
  @ApiResponse({ status: 403, description: 'Test login not enabled' })
  @ApiResponse({ status: 401, description: 'Invalid secret' })
  async testLogin(
    @Body() dto: TestLoginDto,
    @Res({ passthrough: true }) res: Response
  ): Promise<TestLoginResponseDto> {
    const result = await this.testAuthService.testLogin(dto.email, dto.secret);
    this.metricsService.authLogins.inc({
      method: 'test',
      new_user: String(result.isNewUser),
    });

    // Set refresh token cookie (same as normal login for web clients)
    res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);

    return {
      accessToken: result.accessToken,
      refreshToken: result.refreshToken,
      isNewUser: result.isNewUser,
      publicKeyHex: result.publicKeyHex,
      privateKeyHex: result.privateKeyHex,
    };
  }
}

import {
  Controller,
  Get,
  Post,
  Body,
  Header,
  HttpCode,
  HttpStatus,
  Inject,
  Logger,
  UnauthorizedException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse } from '@nestjs/swagger';
import { Throttle, ThrottlerGuard } from '@nestjs/throttler';
import { UseGuards } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import Redis from 'ioredis';
import { parseSiweMessage } from 'viem/siwe';
import { REDIS_CLIENT } from '../../common/redis.module';
import { JwtIssuerService } from '../services/jwt-issuer.service';
import { GoogleOAuthService } from '../services/google-oauth.service';
import { EmailOtpService } from '../services/email-otp.service';
import { SiweService } from '../services/siwe.service';
import { User } from '../entities/user.entity';
import { AuthMethod } from '../entities/auth-method.entity';
import {
  GoogleLoginDto,
  SendOtpDto,
  VerifyOtpDto,
  WalletVerifyDto,
  IdentityTokenResponseDto,
  SendOtpResponseDto,
} from '../dto/identity.dto';

@ApiTags('Identity')
@Controller('auth')
export class IdentityController {
  private readonly logger = new Logger(IdentityController.name);

  constructor(
    private jwtIssuerService: JwtIssuerService,
    private googleOAuthService: GoogleOAuthService,
    private emailOtpService: EmailOtpService,
    private siweService: SiweService,
    @InjectRepository(User)
    private userRepository: Repository<User>,
    @InjectRepository(AuthMethod)
    private authMethodRepository: Repository<AuthMethod>,
    @Inject(REDIS_CLIENT)
    private readonly redis: Redis
  ) {}

  @Get('.well-known/jwks.json')
  @Header('Cache-Control', 'public, max-age=3600')
  @ApiOperation({ summary: 'JWKS endpoint for CipherBox identity provider' })
  @ApiResponse({
    status: 200,
    description: 'JWKS containing RS256 public key for JWT verification',
    schema: {
      type: 'object',
      properties: { keys: { type: 'array', items: { type: 'object' } } },
      required: ['keys'],
    },
  })
  getJwks(): { keys: object[] } {
    return this.jwtIssuerService.getJwksData();
  }

  @Post('identity/google')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary: 'Login with Google OAuth token, returns CipherBox identity JWT',
  })
  @ApiResponse({
    status: 200,
    description: 'CipherBox JWT issued',
    type: IdentityTokenResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Invalid Google token' })
  async googleLogin(@Body() dto: GoogleLoginDto): Promise<IdentityTokenResponseDto> {
    // 1. Verify Google token
    const googlePayload = await this.googleOAuthService.verifyGoogleToken(dto.idToken);
    const normalizedEmail = googlePayload.email?.toLowerCase().trim() ?? '';

    // 2. Link intent: just verify ownership and issue JWT (no user creation)
    if (dto.intent === 'link') {
      const idToken = await this.jwtIssuerService.signIdentityJwt(
        'link-verification',
        normalizedEmail
      );
      this.logger.log(`Google link verification: email=${normalizedEmail}`);
      return { idToken, userId: '', isNewUser: false, email: normalizedEmail };
    }

    // 3. Hash Google sub (immutable user ID) -- NOT email (which can change)
    const identifierHash = this.siweService.hashIdentifier(googlePayload.sub);

    // 4. Find or create user by hashed identifier
    const { user, isNewUser } = await this.findOrCreateUserByIdentifier(
      identifierHash,
      this.siweService.truncateEmail(normalizedEmail),
      'google'
    );

    // 5. Sign CipherBox identity JWT (include email for auth method identifier)
    const idToken = await this.jwtIssuerService.signIdentityJwt(user.id, normalizedEmail);

    this.logger.log(`Google login: userId=${user.id}, isNew=${isNewUser}`);

    return {
      idToken,
      userId: user.id,
      isNewUser,
      email: googlePayload.email,
    };
  }

  @Post('identity/email/send-otp')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ThrottlerGuard)
  @Throttle({ default: { limit: 5, ttl: 900000 } }) // 5 requests per 15 min per IP
  @ApiOperation({ summary: 'Send OTP to email address' })
  @ApiResponse({
    status: 200,
    description: 'OTP sent',
    type: SendOtpResponseDto,
  })
  @ApiResponse({
    status: 400,
    description: 'Invalid email or rate limit exceeded',
  })
  async sendOtp(@Body() dto: SendOtpDto): Promise<SendOtpResponseDto> {
    await this.emailOtpService.sendOtp(dto.email);
    return { success: true };
  }

  @Post('identity/email/verify-otp')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ThrottlerGuard)
  @Throttle({ default: { limit: 5, ttl: 900000 } }) // 5 requests per 15 min per IP
  @ApiOperation({
    summary: 'Verify email OTP and return CipherBox identity JWT',
  })
  @ApiResponse({
    status: 200,
    description: 'OTP verified, JWT issued',
    type: IdentityTokenResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Invalid or expired OTP' })
  async verifyOtp(@Body() dto: VerifyOtpDto): Promise<IdentityTokenResponseDto> {
    // 1. Verify OTP
    await this.emailOtpService.verifyOtp(dto.email, dto.otp);

    // 2. Normalize email
    const normalizedEmail = dto.email.toLowerCase().trim();

    // 3. Link intent: just verify ownership and issue JWT (no user creation)
    if (dto.intent === 'link') {
      const idToken = await this.jwtIssuerService.signIdentityJwt(
        'link-verification',
        normalizedEmail
      );
      this.logger.log(`Email link verification: email=${normalizedEmail}`);
      return { idToken, userId: '', isNewUser: false, email: normalizedEmail };
    }

    // 4. Hash for identifier lookup
    const identifierHash = this.siweService.hashIdentifier(normalizedEmail);

    // 5. Find or create user by hashed identifier
    const { user, isNewUser } = await this.findOrCreateUserByIdentifier(
      identifierHash,
      this.siweService.truncateEmail(normalizedEmail),
      'email'
    );

    // 6. Sign CipherBox identity JWT (include email for auth method identifier)
    const idToken = await this.jwtIssuerService.signIdentityJwt(user.id, normalizedEmail);

    this.logger.log(`Email OTP login: userId=${user.id}, isNew=${isNewUser}`);

    return {
      idToken,
      userId: user.id,
      isNewUser,
      email: normalizedEmail,
    };
  }

  @Get('identity/wallet/nonce')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ThrottlerGuard)
  @Throttle({ default: { limit: 10, ttl: 60000 } }) // 10 per 60s per IP
  @ApiOperation({ summary: 'Generate SIWE nonce for wallet login' })
  @ApiResponse({
    status: 200,
    description: 'Nonce generated',
    schema: {
      type: 'object',
      properties: { nonce: { type: 'string' } },
      required: ['nonce'],
    },
  })
  async getWalletNonce(): Promise<{ nonce: string }> {
    const nonce = this.siweService.generateNonce();
    // Store nonce in Redis with 5min TTL
    await this.redis.set(`siwe:nonce:${nonce}`, '1', 'EX', 300);
    return { nonce };
  }

  @Post('identity/wallet')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ThrottlerGuard)
  @Throttle({ default: { limit: 5, ttl: 900000 } }) // 5 per 15min per IP
  @ApiOperation({
    summary: 'Verify SIWE wallet signature and return CipherBox identity JWT',
  })
  @ApiResponse({
    status: 200,
    description: 'Wallet verified, JWT issued',
    type: IdentityTokenResponseDto,
  })
  @ApiResponse({ status: 401, description: 'Invalid nonce or signature' })
  async walletLogin(@Body() dto: WalletVerifyDto): Promise<IdentityTokenResponseDto> {
    // 1. Parse the message to extract nonce
    const parsed = parseSiweMessage(dto.message);
    if (!parsed.nonce) {
      throw new UnauthorizedException('Invalid SIWE message: missing nonce');
    }

    // 2. Consume nonce from Redis (single-use)
    const nonceKey = `siwe:nonce:${parsed.nonce}`;
    let nonceDeleted: number;
    try {
      nonceDeleted = await this.redis.del(nonceKey);
    } catch (err) {
      this.logger.error('Redis error during nonce consumption', err);
      throw new UnauthorizedException('Nonce verification failed');
    }
    if (!nonceDeleted) {
      throw new UnauthorizedException('Invalid or expired nonce');
    }

    // 3. Verify SIWE message + signature
    const walletAddress = await this.siweService.verifySiweMessage(
      dto.message,
      dto.signature as `0x${string}`,
      parsed.nonce
    );

    // 5. Link intent: just verify ownership and issue JWT (no user creation)
    if (dto.intent === 'link') {
      const idToken = await this.jwtIssuerService.signIdentityJwt('link-verification');
      this.logger.log(`Wallet link verification: address=${walletAddress}`);
      return { idToken, userId: '', isNewUser: false };
    }

    // 6. Find or create user by wallet address hash
    const addressHash = this.siweService.hashWalletAddress(walletAddress);
    const truncated = this.siweService.truncateWalletAddress(walletAddress);
    const { user, isNewUser } = await this.findOrCreateUserByIdentifier(
      addressHash,
      truncated,
      'wallet'
    );

    // 7. Issue CipherBox JWT (sub=userId)
    const idToken = await this.jwtIssuerService.signIdentityJwt(user.id);

    this.logger.log(`Wallet login: userId=${user.id}, isNew=${isNewUser}`);

    return { idToken, userId: user.id, isNewUser };
  }

  /**
   * Find an existing user by hashed identifier in the AuthMethod table, or create a new user.
   *
   * Each auth method type is independent -- no cross-method email matching.
   * Users link methods explicitly via Settings, not auto-linked by email.
   *
   * For identity provider flow, the publicKey is set to a placeholder because
   * the actual MPC-derived publicKey is not known until the client completes
   * Core Kit login with the CipherBox JWT.
   */
  private async findOrCreateUserByIdentifier(
    identifierHash: string,
    identifierDisplay: string,
    authMethodType: 'google' | 'email' | 'wallet'
  ): Promise<{ user: User; isNewUser: boolean }> {
    // Look for existing auth method with this hash
    const existingMethod = await this.authMethodRepository.findOne({
      where: {
        type: authMethodType,
        identifierHash,
      },
      relations: ['user'],
    });

    if (existingMethod) {
      // Update last used timestamp
      existingMethod.lastUsedAt = new Date();
      await this.authMethodRepository.save(existingMethod);
      return { user: existingMethod.user, isNewUser: false };
    }

    // No cross-method linking -- create new user with unique temporary publicKey
    const tempId = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
    const newUser = await this.userRepository.save({
      publicKey: `pending-core-kit-${tempId}`,
    });
    // Update placeholder with actual userId now that we have it
    newUser.publicKey = `pending-core-kit-${newUser.id}`;
    await this.userRepository.save(newUser);

    // Create auth method with hash-based identifier
    await this.authMethodRepository.save({
      userId: newUser.id,
      type: authMethodType,
      identifier: identifierHash,
      identifierHash,
      identifierDisplay,
      lastUsedAt: new Date(),
    });

    return { user: newUser, isNewUser: true };
  }
}

import {
  Controller,
  Post,
  Get,
  Body,
  Query,
  UseGuards,
  Request,
  NotFoundException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth, ApiQuery } from '@nestjs/swagger';
import { Throttle, ThrottlerGuard } from '@nestjs/throttler';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { IpnsService } from './ipns.service';
import {
  PublishIpnsDto,
  PublishIpnsResponseDto,
  BatchPublishIpnsDto,
  BatchPublishIpnsResponseDto,
  ResolveIpnsQueryDto,
  ResolveIpnsResponseDto,
} from './dto';
import { MetricsService } from '../metrics/metrics.service';
import { RequestWithUser } from '../common/types';

@ApiTags('IPNS')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, ThrottlerGuard)
@Controller('ipns')
export class IpnsController {
  constructor(
    private readonly ipnsService: IpnsService,
    private readonly metricsService: MetricsService
  ) {}

  // [SECURITY: HIGH-04] Rate limit IPNS publish to prevent abuse
  // Each publish makes external HTTP calls to the delegated routing service
  @Throttle({ default: { limit: 10, ttl: 60000 } }) // 10 publishes per minute per user
  @Post('publish')
  @ApiOperation({
    summary: 'Publish IPNS record',
    description:
      'Relay a pre-signed IPNS record to the IPFS network via delegated routing. ' +
      'The client signs the record locally; backend relays to the delegated routing service and tracks ' +
      'the folder for TEE republishing.',
  })
  @ApiResponse({
    status: 200,
    description: 'IPNS record published successfully',
    type: PublishIpnsResponseDto,
  })
  @ApiResponse({
    status: 400,
    description: 'Bad Request - Invalid record format or missing required fields',
  })
  @ApiResponse({
    status: 401,
    description: 'Unauthorized - JWT token required',
  })
  @ApiResponse({
    status: 409,
    description:
      'Conflict - expectedSequenceNumber does not match current server sequence number. ' +
      'Response body includes currentSequenceNumber for client re-sync.',
  })
  @ApiResponse({
    status: 502,
    description: 'Bad Gateway - Failed to publish to delegated routing',
  })
  async publishRecord(
    @Request() req: RequestWithUser,
    @Body() dto: PublishIpnsDto
  ): Promise<PublishIpnsResponseDto> {
    const result = await this.ipnsService.publishRecord(req.user.id, dto);
    this.metricsService.ipnsPublishes.inc({ type: 'single' });
    return result;
  }

  // [SECURITY: HIGH-04] Rate limit batch publish - lower limit since each batch can have up to 200 records
  @Throttle({ default: { limit: 5, ttl: 60000 } }) // 5 batch publishes per minute per user
  @Post('publish-batch')
  @ApiOperation({
    summary: 'Batch publish IPNS records',
    description:
      'Publish multiple IPNS records (folder and/or file) in a single API call. ' +
      'Supports up to 200 records per batch with concurrency-limited processing. ' +
      'Partial success is allowed: individual record failures do not fail the batch.',
  })
  @ApiResponse({
    status: 200,
    description: 'Batch publish results with per-record outcomes',
    type: BatchPublishIpnsResponseDto,
  })
  @ApiResponse({
    status: 400,
    description: 'Bad Request - Invalid record format or batch exceeds 200 entries',
  })
  @ApiResponse({
    status: 401,
    description: 'Unauthorized - JWT token required',
  })
  @ApiResponse({
    status: 409,
    description:
      'Conflict - a folder record in the batch has an expectedSequenceNumber that does not match ' +
      'the current server sequence number. The entire batch is rejected.',
  })
  @ApiResponse({
    status: 502,
    description: 'Bad Gateway - Delegated routing failures (partial results may be returned)',
  })
  async publishBatch(
    @Request() req: RequestWithUser,
    @Body() dto: BatchPublishIpnsDto
  ): Promise<BatchPublishIpnsResponseDto> {
    const result = await this.ipnsService.publishBatch(req.user.id, dto);
    this.metricsService.ipnsPublishes.inc({ type: 'batch' }, result.totalSucceeded);
    return result;
  }

  // [SECURITY: HIGH-04] Rate limit IPNS resolve - higher limit than publish since read-only
  @Throttle({ default: { limit: 30, ttl: 60000 } }) // 30 resolves per minute per user
  @Get('resolve')
  @ApiOperation({
    summary: 'Resolve IPNS name',
    description:
      'Resolve an IPNS name to its current CID via delegated routing. ' +
      'Returns the CID and sequence number of the current IPNS record.',
  })
  @ApiQuery({
    name: 'ipnsName',
    description:
      'IPNS name to resolve. Supports CIDv1 IPNS names starting with "k51..." (PeerID-style) or "bafzaa..." (IPNS key CID).',
    example: 'REDACTED',
  })
  @ApiResponse({
    status: 200,
    description: 'IPNS name resolved successfully',
    type: ResolveIpnsResponseDto,
  })
  @ApiResponse({
    status: 400,
    description: 'Bad Request - Invalid IPNS name format',
  })
  @ApiResponse({
    status: 401,
    description: 'Unauthorized - JWT token required',
  })
  @ApiResponse({
    status: 404,
    description: 'Not Found - IPNS name not published or not found in routing network',
  })
  @ApiResponse({
    status: 502,
    description: 'Bad Gateway - Failed to resolve from delegated routing',
  })
  async resolveRecord(@Query() query: ResolveIpnsQueryDto): Promise<ResolveIpnsResponseDto> {
    const result = await this.ipnsService.resolveRecord(query.ipnsName);

    if (!result) {
      throw new NotFoundException('IPNS name not found in routing network');
    }

    // Track resolve source: if signatureV2 is present, it came from the network
    const source = result.signatureV2 ? 'network' : 'db_cache';
    this.metricsService.ipnsResolves.inc({ source });

    // Include signature fields as all-or-nothing bundle for client verification
    const hasSigData = result.signatureV2 && result.data && result.pubKey;
    return {
      success: true,
      cid: result.cid,
      sequenceNumber: result.sequenceNumber,
      ...(hasSigData && {
        signatureV2: result.signatureV2,
        data: result.data,
        pubKey: result.pubKey,
      }),
    };
  }
}

import {
  Controller,
  Post,
  Get,
  Delete,
  Body,
  Param,
  UseGuards,
  Request,
  ParseUUIDPipe,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth } from '@nestjs/swagger';
import { ThrottlerGuard, Throttle } from '@nestjs/throttler';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { AllowScope } from '../auth/decorators/allow-scope.decorator';
import { DeviceApprovalService } from './device-approval.service';
import { CreateApprovalDto } from './dto/create-approval.dto';
import { RespondApprovalDto } from './dto/respond-approval.dto';
import { RequestWithUser } from '../common/types';

@ApiTags('device-approval')
@ApiBearerAuth()
@AllowScope('device-approval')
@UseGuards(JwtAuthGuard, ThrottlerGuard)
@Controller('device-approval')
export class DeviceApprovalController {
  constructor(private readonly deviceApprovalService: DeviceApprovalService) {}

  @Post('request')
  @Throttle({ default: { limit: 3, ttl: 60000 } })
  @ApiOperation({
    summary: 'Create device approval request',
    description:
      'New device creates an approval request with an ephemeral ' +
      'public key for ECIES key exchange. Request expires after ' +
      '5 minutes.',
  })
  @ApiResponse({
    status: 201,
    description: 'Approval request created',
    schema: {
      properties: {
        requestId: { type: 'string', format: 'uuid' },
      },
    },
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async createRequest(
    @Request() req: RequestWithUser,
    @Body() dto: CreateApprovalDto
  ): Promise<{ requestId: string }> {
    return this.deviceApprovalService.createRequest(req.user.id, dto);
  }

  @Get(':requestId/status')
  @ApiOperation({
    summary: 'Poll approval request status',
    description:
      'New device polls this endpoint to check if the request ' +
      'has been approved, denied, or expired. Returns the ' +
      'encrypted factor key on approval.',
  })
  @ApiResponse({
    status: 200,
    description: 'Approval status',
    schema: {
      properties: {
        status: {
          type: 'string',
          enum: ['pending', 'approved', 'denied', 'expired'],
        },
        encryptedFactorKey: {
          type: 'string',
          nullable: true,
          description: 'ECIES-encrypted factor key (hex)',
        },
      },
    },
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  @ApiResponse({
    status: 404,
    description: 'Request not found',
  })
  async getStatus(
    @Request() req: RequestWithUser,
    @Param('requestId', ParseUUIDPipe) requestId: string
  ): Promise<{ status: string; encryptedFactorKey?: string }> {
    return this.deviceApprovalService.getStatus(requestId, req.user.id);
  }

  @Get('pending')
  @ApiOperation({
    summary: 'List pending approval requests',
    description:
      'Existing device fetches all non-expired pending approval ' +
      'requests for the authenticated user.',
  })
  @ApiResponse({
    status: 200,
    description: 'List of pending approval requests',
    schema: {
      type: 'array',
      items: {
        properties: {
          requestId: { type: 'string', format: 'uuid' },
          deviceId: { type: 'string' },
          deviceName: { type: 'string' },
          ephemeralPublicKey: { type: 'string' },
          createdAt: { type: 'string', format: 'date-time' },
          expiresAt: { type: 'string', format: 'date-time' },
        },
      },
    },
  })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  async getPending(@Request() req: RequestWithUser): Promise<
    Array<{
      requestId: string;
      deviceId: string;
      deviceName: string;
      ephemeralPublicKey: string;
      createdAt: Date;
      expiresAt: Date;
    }>
  > {
    return this.deviceApprovalService.getPending(req.user.id);
  }

  @Post(':requestId/respond')
  @ApiOperation({
    summary: 'Respond to approval request',
    description:
      'Existing device approves or denies an approval request. ' +
      'On approve, includes the ECIES-encrypted factor key.',
  })
  @ApiResponse({
    status: 200,
    description: 'Response recorded',
  })
  @ApiResponse({ status: 400, description: 'Already responded or expired' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  @ApiResponse({ status: 404, description: 'Request not found' })
  async respond(
    @Request() req: RequestWithUser,
    @Param('requestId', ParseUUIDPipe) requestId: string,
    @Body() dto: RespondApprovalDto
  ): Promise<void> {
    return this.deviceApprovalService.respond(requestId, req.user.id, dto);
  }

  @Delete(':requestId')
  @ApiOperation({
    summary: 'Cancel approval request',
    description:
      'New device cancels its own pending approval request ' +
      '(cleanup on navigation away or recovery phrase used).',
  })
  @ApiResponse({ status: 200, description: 'Request cancelled' })
  @ApiResponse({ status: 401, description: 'Unauthorized' })
  @ApiResponse({
    status: 404,
    description: 'Request not found or not pending',
  })
  async cancel(
    @Request() req: RequestWithUser,
    @Param('requestId', ParseUUIDPipe) requestId: string
  ): Promise<void> {
    return this.deviceApprovalService.cancel(requestId, req.user.id);
  }
}

