export function testFetch(url: string, init?: RequestInit): Promise<Response> {
  const headers = new Headers(init?.headers);
  if (THROTTLE_BYPASS) {
    headers.set('X-Throttle-Bypass', THROTTLE_BYPASS);
  }
  return fetch(url, { ...init, headers });
}

