 1→import { Injectable, ExecutionContext } from '@nestjs/common';
 2→import { ThrottlerGuard } from '@nestjs/throttler';
 3→
 4→/**
 5→ * Extends ThrottlerGuard with a bypass header for test environments.
 6→ *
 7→ * When `THROTTLE_BYPASS_SECRET` is set and a request includes a matching
 8→ * `X-Throttle-Bypass` header, rate limiting is skipped. This allows SDK
 9→ * E2E and load tests to run against staging without hitting 429s.
10→ *
11→ * Security:
12→ *   - Production never sets the secret, so bypass is impossible
13→ *   - If the env var is unset/empty, the header is ignored entirely
14→ *   - Constant-time comparison prevents timing attacks
15→ */
16→@Injectable()
17→export class BypassableThrottlerGuard extends ThrottlerGuard {
18→  async canActivate(context: ExecutionContext): Promise<boolean> {
19→    const secret = process.env.THROTTLE_BYPASS_SECRET;
20→
21→    if (secret) {
22→      const request = context.switchToHttp().getRequest();
23→      const header: string | undefined = request.headers['x-throttle-bypass'];
24→      if (header && timingSafeEqual(header, secret)) {
25→        return true;
26→      }
27→    }
28→
29→    return super.canActivate(context);
30→  }
31→}
32→
33→/** Constant-time string comparison to prevent timing attacks on the secret. */
34→function timingSafeEqual(a: string, b: string): boolean {
35→  if (a.length !== b.length) return false;
36→  let result = 0;
37→  for (let i = 0; i < a.length; i++) {
38→    result |= a.charCodeAt(i) ^ b.charCodeAt(i);
39→  }
40→  return result === 0;
41→}
