103→ * Aggregate metrics from all pool clients, print summary, and return metrics.
104→ * Extracts the repeated boilerplate from every load test scenario.
105→ */
106→export function aggregateAndReport(scenarioName: string, pool: PoolClient[]): OperationMetrics[] {
107→  const allMetrics = new MetricsCollector();
108→  allMetrics.start();
109→
110→  let minTimestamp = Infinity;
111→  let maxTimestamp = 0;
112→
113→  for (const pc of pool) {
114→    for (const sample of pc.metrics.getReadonlySamples()) {
115→      allMetrics.record(sample);
116→      if (sample.timestamp < minTimestamp) minTimestamp = sample.timestamp;
117→      if (sample.timestamp > maxTimestamp) maxTimestamp = sample.timestamp;
118→    }
119→  }
120→  allMetrics.stop();
121→
122→  const totalDuration = maxTimestamp > minTimestamp ? maxTimestamp - minTimestamp : 0;
123→  const metrics = allMetrics.getMetrics();
124→
125→  printSummary(scenarioName, metrics, totalDuration, pool.length);
126→  console.log('\nJSON Report:\n' + toJsonReport(scenarioName, metrics, totalDuration, pool.length));
127→
128→  return metrics;
129→}
